    // ==================== SummaryPopup / SummaryConfig ====================

    /**
     * One "fancy textbox" shown during the end-of-video summary segment. Several
     * of these can be placed at different locations and times. Each reuses the
     * app's existing text machinery: the Texts-Timer entrance effects (Fade /
     * Slide In / Pop / …), the per-text style effects (Glow / Neon / Rainbow /
     * Typewriter / …) and the SlideTextData box styling (rounded corners, shadow,
     * glow, border), so a popup is drawn by the same renderFrame path as
     * everything else — which is what makes the live preview identical to the
     * exported video.
     */
    static class SummaryPopup {
        boolean enabled = true;
        String  text = "";
        double  appearSec = 0.0;         // when this popup appears, seconds into the segment
        double  durationSec = 5.0;       // how long it stays visible once it appears

        // ---- Entrance animation (same names as the Texts-Timer APPEAR_EFFECTS) ----
        String  entrance = "Pop";        // None, Fade, Slide In Top/Bottom/Left/Right,
                                         // Scale Up, Zoom Out, Bounce, Rotate In, Pop
        String  easing   = "Ease Out";   // Linear, Ease In, Ease Out, Ease In Out, Bounce
        int     animMs   = 600;          // entrance duration in ms

        // ---- Text styling ----
        String  fontName = "Segoe UI";
        int     fontSize = 64;           // relative to a 1080p frame (auto-scales up at 2K/4K)
        boolean bold = true;
        boolean italic = false;
        Color   textColor = Color.WHITE;
        // Second colour used by the effects that take two (Cartoon Pop, Gold Pop,
        // Neon + Shadow, Glow + Outline, Outline + Shadow, …) as the outline / glow
        // accent. Fed to the renderer as the text's highlight colour when no words
        // are highlighted.
        Color   accentColor = new Color(120, 80, 210);
        int     alignment = SwingConstants.CENTER;
        String  textEffect = "Glow";     // one of TEXT_EFFECTS
        int     textEffectIntensity = 60;
        int     lineSpacing = 8;

        // ---- Highlight specific word(s) ----
        // Comma-separated word(s)/phrase(s) inside `text` to highlight. Empty = off.
        String  highlightWords = "";
        Color   highlightColor = new Color(255, 210, 60);
        String  highlightStyle = "Marker"; // one of HIGHLIGHT_STYLES (excluding "None")
        // Fine control over the highlight mark, each a percentage (100 = default):
        // intensity scales the highlight's opacity, height/width scale its size.
        int     highlightIntensity = 100; // 0..100
        int     highlightHeight = 100;    // 50..200
        int     highlightWidth = 100;     // 50..200

        // ---- Position + wrap width (percent of frame) ----
        int     xPct = 50;
        int     yPct = 50;
        int     widthPct = 80;

        // ---- Fancy box ----
        Color   boxColor = new Color(20, 20, 32);
        int     boxOpacity = 82;         // 0 = no box (text only)
        int     boxRoundPct = 28;
        int     boxPadPct = 70;
        int     boxPadYPct = 70;
        boolean boxShadow = true;
        boolean boxGlow = false;
        Color   boxGlowColor = new Color(90, 160, 255);
        // None, Solid, Double, Dashed, Dotted, Groove, Gradient, Corners
        String  boxBorderStyle = "None";
        Color   boxBorderColor = Color.WHITE;
        int     boxBorderWidth = 3;

        /** True when this popup contributes anything to the segment. */
        boolean isLive() { return enabled && text != null && !text.trim().isEmpty(); }

        /** Seconds from segment start until this popup is gone. */
        double endSec() { return appearSec + Math.max(0.0, durationSec); }

        void copyFrom(SummaryPopup o) {
            enabled = o.enabled; text = o.text; appearSec = o.appearSec; durationSec = o.durationSec;
            entrance = o.entrance; easing = o.easing; animMs = o.animMs;
            fontName = o.fontName; fontSize = o.fontSize; bold = o.bold; italic = o.italic;
            textColor = o.textColor; accentColor = o.accentColor; alignment = o.alignment;
            textEffect = o.textEffect; textEffectIntensity = o.textEffectIntensity;
            lineSpacing = o.lineSpacing;
            highlightWords = o.highlightWords; highlightColor = o.highlightColor; highlightStyle = o.highlightStyle;
            highlightIntensity = o.highlightIntensity; highlightHeight = o.highlightHeight; highlightWidth = o.highlightWidth;
            xPct = o.xPct; yPct = o.yPct; widthPct = o.widthPct;
            boxColor = o.boxColor; boxOpacity = o.boxOpacity; boxRoundPct = o.boxRoundPct;
            boxPadPct = o.boxPadPct; boxPadYPct = o.boxPadYPct;
            boxShadow = o.boxShadow; boxGlow = o.boxGlow; boxGlowColor = o.boxGlowColor;
            boxBorderStyle = o.boxBorderStyle; boxBorderColor = o.boxBorderColor;
            boxBorderWidth = o.boxBorderWidth;
        }

        SummaryPopup duplicate() { SummaryPopup c = new SummaryPopup(); c.copyFrom(this); return c; }
    }

    /**
     * The whole end-of-video summary segment: a shared backdrop plus a list of
     * {@link SummaryPopup} boxes. Plays after the slideshow finishes and adds its
     * length ({@link #segmentDurationSec}) to the exported MP4. Project-level,
     * edited via the "Summary…" toolbar button, persisted with the preset, and
     * applied as a final concat pass in createMp4().
     */
    static class SummaryConfig {
        boolean enabled = false;
        // Backdrop behind the popups for the whole segment.
        // Freeze Last Frame, Blur Last Frame, Blur + Vignette, Duotone, Gradient, Solid Color
        String  bgMode = "Freeze Last Frame";
        Color   bgColor = Color.BLACK;
        int     bgDim = 45;                    // darken 0..100 over the frozen / blurred frame
        final java.util.List<SummaryPopup> popups = new java.util.ArrayList<>();

        SummaryConfig() { popups.add(new SummaryPopup()); }

        /** Length of the appended segment = the moment the last live popup ends. */
        double segmentDurationSec() {
            double m = 0;
            for (SummaryPopup p : popups) if (p.isLive()) m = Math.max(m, p.endSec());
            return m;
        }

        /** True when the segment should actually be appended at export. */
        boolean active() { return enabled && segmentDurationSec() > 0.0; }

        void copyFrom(SummaryConfig o) {
            enabled = o.enabled; bgMode = o.bgMode; bgColor = o.bgColor; bgDim = o.bgDim;
            popups.clear();
            for (SummaryPopup p : o.popups) popups.add(p.duplicate());
            if (popups.isEmpty()) popups.add(new SummaryPopup());
        }

        SummaryConfig duplicate() { SummaryConfig c = new SummaryConfig(); c.copyFrom(this); return c; }
    }

    // ==================== SlidePictureData ====================

    // ==================== Image FX catalogue (toolbar row 4e2) ====================
    /** Over everything on the slide. What slide pictures have always done. */
    static final String PIC_LAYER_FRONT = "Front";
    /** Over the slide image or video, but under text, numbers and annotations. */
    static final String PIC_LAYER_BEHIND = "Behind Text";
    /** Full-bleed under everything: the picture becomes the slide's backdrop,
     *  covering the slide image or video entirely. */
    static final String PIC_LAYER_BACKGROUND = "Background";

    /** Layer choices, in the order the dropdown lists them. */
    static final String[] PIC_LAYERS = {PIC_LAYER_FRONT, PIC_LAYER_BEHIND, PIC_LAYER_BACKGROUND};

    /** Default accent colour for glow / neon / tint effects: warm gold. */
    static final Color PIC_FX_DEFAULT_COLOR = new Color(255, 205, 90);

    /** Motion effects. They move, scale or rotate the whole picture. */
    static final String[] PIC_FX_MOTION = {
            "Ken Burns", "Scale Pulse", "Pop", "Heartbeat", "Bounce",
            "Float", "Sway", "Spin", "Tilt 3D"
    };
    /** Light effects painted around / over the picture. */
    static final String[] PIC_FX_LIGHT = {
            "Glow", "Neon Outline", "Shine", "Shimmer", "Sparkle",
            "Lens Flare", "Light Rays", "Pulse Ring", "Glow Sweep"
    };
    /** Colour grades and film looks. These re-map the picture's pixels. */
    static final String[] PIC_FX_COLOR = {
            "Color Scan", "RGB Split", "Duotone", "Monochrome", "Sepia Tone",
            "Film Grain", "Scanlines", "Holographic", "Gradient Tint", "Soft Focus"
    };
    /** Framing and depth: what makes a picture sit on the slide instead of in it. */
    static final String[] PIC_FX_FRAME = {
            "Drop Shadow", "Reflection", "Inner Shadow", "Vignette",
            "Corner Accents", "Frame Trace", "Dust Motes"
    };
    /** Entrance animations, played once at the start of the slide. */
    static final String[] PIC_FX_ENTRANCES = {
            "None", "Fade In", "Zoom In", "Zoom Out", "Slide In Left", "Slide In Right",
            "Slide In Top", "Slide In Bottom", "Flip In", "Rotate In", "Blur In",
            "Unfold", "Drop In", "Pop In"
    };

    /** Every effect name, in menu order. */
    static String[] picFxAll() {
        List<String> all = new ArrayList<>();
        for (String[] grp : new String[][]{PIC_FX_MOTION, PIC_FX_LIGHT, PIC_FX_COLOR, PIC_FX_FRAME}) {
            all.addAll(Arrays.asList(grp));
        }
        return all.toArray(new String[0]);
    }

    /**
     * A ready-made look: the effects it switches on plus the knob settings that
     * make it read the way its name promises. Order is
     * {effects, intensity, speed, colour, entrance, entranceSeconds, shadow}.
     */
    static final class PicFxPreset {
        final String effects; final int intensity; final int speed; final Color color;
        final String entrance; final double entranceSec; final int shadow;
        PicFxPreset(String effects, int intensity, int speed, Color color,
                    String entrance, double entranceSec, int shadow) {
            this.effects = effects; this.intensity = intensity; this.speed = speed;
            this.color = color; this.entrance = entrance; this.entranceSec = entranceSec;
            this.shadow = shadow;
        }
    }

    /** Placeholder row at the top of the Image FX preset dropdown. */
    static final String PIC_FX_PRESET_NONE = "— Preset —";

    private static final java.util.Map<String, String> PIC_FX_TIPS = buildPicFxTips();

    private static java.util.Map<String, String> buildPicFxTips() {
        java.util.LinkedHashMap<String, String> m = new java.util.LinkedHashMap<>();
        // Motion
        m.put("Ken Burns", "Slow documentary push: the picture zooms and drifts inside its frame.");
        m.put("Scale Pulse", "Gentle, continuous breathe in and out.");
        m.put("Pop", "Quick punch up to full size, then settle. Repeats every second.");
        m.put("Heartbeat", "Double beat — a strong thump followed by a softer one.");
        m.put("Bounce", "Lifts off its baseline and drops back.");
        m.put("Float", "Barely-there vertical drift, as if suspended.");
        m.put("Sway", "Slow rocking tilt a couple of degrees either way.");
        m.put("Spin", "Full slow rotation. Best on circular crops and badges.");
        m.put("Tilt 3D", "Perspective-style lean that swings left and right.");
        // Glow & Light
        m.put("Glow", "Soft pulsing halo in the accent colour.");
        m.put("Neon Outline", "Bright neon rim with a hot white core and a subtle flicker.");
        m.put("Shine", "A hard specular band sweeping diagonally across the picture.");
        m.put("Shimmer", "A wide, soft accent-tinted wash drifting slowly across.");
        m.put("Sparkle", "Four-point twinkles fading in and out over the picture.");
        m.put("Lens Flare", "A travelling flare with secondary orbs along its axis.");
        m.put("Light Rays", "Slowly rotating god-rays fanning out behind the picture.");
        m.put("Pulse Ring", "Rings of the picture's own outline expanding and fading away.");
        m.put("Glow Sweep", "A glowing comet running around the picture's edge.");
        // Color & Film
        m.put("Color Scan", "A tech scan line sweeping top to bottom, tinting as it goes.");
        m.put("RGB Split", "Chromatic aberration: red and blue channels pulled apart.");
        m.put("Duotone", "Two-tone poster grade built from the accent colour.");
        m.put("Monochrome", "Clean black and white conversion.");
        m.put("Sepia Tone", "Warm archival print look.");
        m.put("Film Grain", "Animated stock grain over the picture.");
        m.put("Scanlines", "Fine CRT line pattern.");
        m.put("Holographic", "Iridescent hue sheen that drifts across the surface.");
        m.put("Gradient Tint", "Accent-colour gradient washing over one corner.");
        m.put("Soft Focus", "Dreamy diffusion — a blurred copy blended back over the sharp one.");
        // Frame & Depth
        m.put("Drop Shadow", "Soft cast shadow. Depth is set by the Depth spinner.");
        m.put("Reflection", "Mirrored, fading copy of the picture just beneath it.");
        m.put("Inner Shadow", "Darkens the picture's own edges so it reads as inset.");
        m.put("Vignette", "Darkened corners that pull the eye to the centre.");
        m.put("Corner Accents", "Pulsing bracket marks at the four corners.");
        m.put("Frame Trace", "A light segment tracing the outline once per cycle.");
        m.put("Dust Motes", "Fine particles drifting upward around the picture.");
        return m;
    }

    /** Tooltip for one Image FX effect. */
    static String picFxTip(String name) {
        String tip = PIC_FX_TIPS.get(name);
        return tip != null ? tip : name;
    }

