    static class SlidePictureData {
        final boolean show;
        final transient BufferedImage image;
        final File imageFile;
        final int x;       // center X as % of frame width
        final int y;       // center Y as % of frame height
        final int widthPct; // picture width as % of frame width
        final String shape; // "Rectangle" or "Circle"
        final int cornerRadius; // corner radius for Rectangle (0 = sharp)
        final File audioFile;       // audio tied to this picture (bulk grid)
        final int audioDurationMs;  // duration of audioFile in ms, -1 = unknown
        final String audioEffect;   // "None", "Glow", "Scale Pulse", "Bounce"
        // Max height as % of frame height. 0 = legacy width-only sizing (height
        // follows aspect ratio). When > 0, the image is fit (aspect-preserved)
        // inside a widthPct × boxHeightPct box so bulk-grid cells never overflow.
        final int boxHeightPct;
        // Index into the slide's audioFiles list at which this image's audio
        // appears. -1 means "always animate the effect"; when >= 0 the effect
        // only shows while that audio segment is active (activeIdx matches).
        final int audioActiveIdx;
        final int borderWidth;   // stroke width in px around each image (0 = none)
        final Color borderColor; // border colour (null → Color.WHITE)
        final int opacity;       // 0-100, 100 = fully opaque
        final String fitMode;    // "Fit" (letterbox) or "Fill" (cover-crop)

        // ---- Image FX (toolbar row 4e2) ----
        // Comma-separated effect names from PIC_FX_ALL, e.g. "Ken Burns,Glow,Drop Shadow".
        // Empty means the picture draws on the fast path with no per-frame work.
        final String fxEffects;
        final int fxIntensity;      // 0-300 %, 100 = designed strength
        final int fxSpeed;          // 10-400 %, 100 = designed tempo
        final Color fxColor;        // accent / glow colour (null = PIC_FX_DEFAULT_COLOR)
        final String fxEntrance;    // one of PIC_FX_ENTRANCES, "None" = appear instantly
        final double fxEntranceSec; // entrance duration in seconds
        final int fxShadow;         // 0-100 drop-shadow depth (0 = no shadow)
        // Where the picture sits in the stack: PIC_LAYER_FRONT (over everything,
        // the original behaviour), PIC_LAYER_BEHIND (over the slide image/video
        // but under text) or PIC_LAYER_BACKGROUND (full-bleed, replacing the
        // slide image/video). Never null.
        final String fxLayer;

        SlidePictureData(boolean show, BufferedImage image, File imageFile,
                         int x, int y, int widthPct, String shape, int cornerRadius) {
            this(show, image, imageFile, x, y, widthPct, shape, cornerRadius, null, -1, "None", 0, -1, 0, null, 100, "Fit");
        }

        SlidePictureData(boolean show, BufferedImage image, File imageFile,
                         int x, int y, int widthPct, String shape, int cornerRadius,
                         File audioFile, int audioDurationMs, String audioEffect) {
            this(show, image, imageFile, x, y, widthPct, shape, cornerRadius,
                    audioFile, audioDurationMs, audioEffect, 0, -1, 0, null, 100, "Fit");
        }

        SlidePictureData(boolean show, BufferedImage image, File imageFile,
                         int x, int y, int widthPct, String shape, int cornerRadius,
                         File audioFile, int audioDurationMs, String audioEffect,
                         int boxHeightPct) {
            this(show, image, imageFile, x, y, widthPct, shape, cornerRadius,
                    audioFile, audioDurationMs, audioEffect, boxHeightPct, -1, 0, null, 100, "Fit");
        }

        SlidePictureData(boolean show, BufferedImage image, File imageFile,
                         int x, int y, int widthPct, String shape, int cornerRadius,
                         File audioFile, int audioDurationMs, String audioEffect,
                         int boxHeightPct, int audioActiveIdx) {
            this(show, image, imageFile, x, y, widthPct, shape, cornerRadius,
                    audioFile, audioDurationMs, audioEffect, boxHeightPct, audioActiveIdx, 0, null, 100, "Fit");
        }

        SlidePictureData(boolean show, BufferedImage image, File imageFile,
                         int x, int y, int widthPct, String shape, int cornerRadius,
                         File audioFile, int audioDurationMs, String audioEffect,
                         int boxHeightPct, int audioActiveIdx,
                         int borderWidth, Color borderColor, int opacity, String fitMode) {
            this(show, image, imageFile, x, y, widthPct, shape, cornerRadius,
                    audioFile, audioDurationMs, audioEffect, boxHeightPct, audioActiveIdx,
                    borderWidth, borderColor, opacity, fitMode,
                    "", 100, 100, null, "None", 0.8, 0, PIC_LAYER_FRONT);
        }

        /** Master constructor - every field, Image FX included. */
        SlidePictureData(boolean show, BufferedImage image, File imageFile,
                         int x, int y, int widthPct, String shape, int cornerRadius,
                         File audioFile, int audioDurationMs, String audioEffect,
                         int boxHeightPct, int audioActiveIdx,
                         int borderWidth, Color borderColor, int opacity, String fitMode,
                         String fxEffects, int fxIntensity, int fxSpeed, Color fxColor,
                         String fxEntrance, double fxEntranceSec, int fxShadow,
                         String fxLayer) {
            this.fxEffects = fxEffects != null ? fxEffects : "";
            this.fxLayer = fxLayer != null && !fxLayer.isEmpty() ? fxLayer : PIC_LAYER_FRONT;
            this.fxIntensity = fxIntensity;
            this.fxSpeed = fxSpeed;
            this.fxColor = fxColor;
            this.fxEntrance = fxEntrance != null ? fxEntrance : "None";
            this.fxEntranceSec = fxEntranceSec;
            this.fxShadow = fxShadow;
            this.show = show;
            this.image = image;
            this.imageFile = imageFile;
            this.x = x;
            this.y = y;
            this.widthPct = widthPct;
            this.shape = shape != null ? shape : "Rectangle";
            this.cornerRadius = cornerRadius;
            this.audioFile = audioFile;
            this.audioDurationMs = audioDurationMs;
            this.audioEffect = audioEffect != null ? audioEffect : "None";
            this.boxHeightPct = boxHeightPct;
            this.audioActiveIdx = audioActiveIdx;
            this.borderWidth = borderWidth;
            this.borderColor = borderColor;
            this.opacity = opacity;
            this.fitMode = fitMode != null ? fitMode : "Fit";
        }

        /** Copy of this slot with a new Image FX configuration. */
        SlidePictureData withFx(String fxEffects, int fxIntensity, int fxSpeed, Color fxColor,
                                String fxEntrance, double fxEntranceSec, int fxShadow,
                                String fxLayer) {
            return new SlidePictureData(show, image, imageFile, x, y, widthPct, shape, cornerRadius,
                    audioFile, audioDurationMs, audioEffect, boxHeightPct, audioActiveIdx,
                    borderWidth, borderColor, opacity, fitMode,
                    fxEffects, fxIntensity, fxSpeed, fxColor, fxEntrance, fxEntranceSec, fxShadow,
                    fxLayer);
        }

        /** Copy of this slot carrying another slot's Image FX configuration. */
        SlidePictureData withFxFrom(SlidePictureData src) {
            if (src == null) return this;
            return withFx(src.fxEffects, src.fxIntensity, src.fxSpeed, src.fxColor,
                    src.fxEntrance, src.fxEntranceSec, src.fxShadow, src.fxLayer);
        }

        /**
         * This picture reshaped to cover the whole frame, for the Background
         * layer. Position, width, shape, corner radius and border all stop
         * meaning anything once the picture is the backdrop, so they are
         * replaced by a centred, cover-cropped, full-frame box. Opacity and
         * every Image FX setting carry over untouched — a Ken Burns push or a
         * vignette on the backdrop is exactly the point.
         */
        SlidePictureData asFullBleed() {
            return new SlidePictureData(show, image, imageFile, 50, 50, 100, "Rectangle", 0,
                    audioFile, audioDurationMs, audioEffect, 100, audioActiveIdx,
                    0, borderColor, opacity, "Fill",
                    fxEffects, fxIntensity, fxSpeed, fxColor, fxEntrance, fxEntranceSec, fxShadow,
                    fxLayer);
        }

        /** True when this picture carries any Image FX at all. */
        boolean hasImageFx() {
            if (fxEffects != null && !fxEffects.isEmpty()) return true;
            if (fxShadow > 0) return true;
            return fxEntrance != null && !fxEntrance.isEmpty() && !fxEntrance.equals("None");
        }

        /** Effects that look identical on every frame, so they never justify
         *  paying for the per-frame export path. */
        private static final Set<String> STATIC_FX = new HashSet<>(Arrays.asList(
                "Drop Shadow", "Reflection", "Inner Shadow", "Vignette",
                "Monochrome", "Sepia Tone", "Duotone", "Gradient Tint",
                "Soft Focus", "Scanlines"));

        /** True when this picture actually moves or flickers frame to frame. */
        boolean hasAnimatedImageFx() {
            if (fxEntrance != null && !fxEntrance.isEmpty() && !fxEntrance.equals("None")) return true;
            if (fxEffects == null || fxEffects.isEmpty()) return false;
            for (String tok : fxEffects.split(",")) {
                String t = tok.trim();
                if (!t.isEmpty() && !"None".equals(t) && !STATIC_FX.contains(t)) return true;
            }
            return false;
        }
    }

    // ==================== Word Timing (Karaoke) ====================
    /**
     * One word with its audio-relative start/end time in seconds. Produced by
     * ElevenLabs Scribe and used by the renderer to highlight whichever source
     * word is being spoken at the current frame.
     */
    /** Built-in motion "whoosh" — a short synthesized swept tone with a soft
     *  attack/decay envelope, so a moving text gets an audible cue with no
     *  external sound file. Rendered on the fly with javax.sound.sampled and
     *  played asynchronously so it never blocks the animation timer. */
    /**
     * The built-in motion cues — the sounds a timed text action fires when it
     * plays. Every one is synthesized here rather than shipped as an asset (the
     * same approach as SlideTimer's countdown sounds): one PCM buffer per cue,
     * cached, played through a Clip for the previews and written out as a WAV
     * that the exporter mixes onto the finished video with ffmpeg.
     *
     * An action stores the cue it wants by name, or the empty string / "(Default)"
     * for "whatever the default is" — so changing the default re-voices every
     * action that never picked its own. The default lives in
     * ~/.gifslideshow/motion-sound.txt so it survives restarts.
     */
    static final class MotionSound {
        private static final float SR = 44100f;
        private static final javax.sound.sampled.AudioFormat FORMAT =
                new javax.sound.sampled.AudioFormat(SR, 16, 1, true, false);

        /** Picker entry meaning "use the default sound", and the silent entry. */
        static final String DEFAULT_CHOICE = "(Default)";
        static final String NONE = "None";
        /** The cue every action falls back to until the user sets another. */
        static final String FALLBACK_DEFAULT = "Whoosh";

        /** Every built-in cue, in picker order: the movement family first, then
         *  the accents, the impacts and the sparkle. */
        static final String[] NAMES = {
                "Whoosh", "Soft Swoosh", "Air Swipe", "Fast Sweep", "Reverse Swell",
                "Pop", "Click", "Snap", "Page Turn", "Typewriter",
                "Impact", "Sub Drop", "Riser", "Shimmer", "Magic Chime" };

        /** Choices for a per-action picker: the default placeholder, silence, then
         *  every cue by name. */
        static String[] actionChoices() {
            String[] out = new String[NAMES.length + 2];
            out[0] = DEFAULT_CHOICE;
            out[1] = NONE;
            System.arraycopy(NAMES, 0, out, 2, NAMES.length);
            return out;
        }

        /** Choices for the default picker: silence, then every cue (no "(Default)"
         *  — that would point at itself). */
        static String[] defaultChoices() {
            String[] out = new String[NAMES.length + 1];
            out[0] = NONE;
            System.arraycopy(NAMES, 0, out, 1, NAMES.length);
            return out;
        }

        static boolean isBuiltIn(String name) {
            if (name == null) return false;
            for (String n : NAMES) if (n.equals(name)) return true;
            return false;
        }

        // ---- the default cue, remembered between runs -------------------------

        private static String defaultName;   // null until first read from disk

        private static File defaultFile() {
            return new File(System.getProperty("user.home"), ".gifslideshow/motion-sound.txt");
        }

        /** The cue "(Default)" resolves to — {@link #FALLBACK_DEFAULT} until the
         *  user picks another, then whatever they last chose. */
        static synchronized String defaultName() {
            if (defaultName == null) {
                String v = null;
                try {
                    File f = defaultFile();
                    if (f.isFile()) {
                        v = new String(java.nio.file.Files.readAllBytes(f.toPath()),
                                java.nio.charset.StandardCharsets.UTF_8).trim();
                    }
                } catch (Exception ignored) { }
                defaultName = (isBuiltIn(v) || NONE.equals(v)) ? v : FALLBACK_DEFAULT;
            }
            return defaultName;
        }

        /** Set the cue every "(Default)" action plays, and remember it on disk.
         *  A write failure only costs the setting its persistence. */
        static synchronized void setDefaultName(String name) {
            if (!isBuiltIn(name) && !NONE.equals(name)) return;
            defaultName = name;
            try {
                File f = defaultFile();
                File dir = f.getParentFile();
                if (dir != null) dir.mkdirs();
                try (java.io.Writer w = new java.io.OutputStreamWriter(
                        new java.io.FileOutputStream(f), java.nio.charset.StandardCharsets.UTF_8)) {
                    w.write(name);
                }
            } catch (Exception ignored) { }
        }

        /**
         * The cue an action actually plays, or null for silence.
         *
         * "(Default)" (and the empty string every pre-sound action carries) means
         * the default cue on a Move / Move Copy and silence on an in-place effect
         * — exactly what those kinds did before this picker existed, so no saved
         * project starts making noise it never made. Pick a cue by name on a
         * Pulse or Shake and it plays that.
         */
        static String resolve(String choice, boolean isMove) {
            String s = choice == null ? "" : choice.trim();
            if (s.isEmpty() || DEFAULT_CHOICE.equals(s)) {
                if (!isMove) return null;
                String d = defaultName();
                return NONE.equals(d) ? null : d;
            }
            if (NONE.equals(s)) return null;
            return isBuiltIn(s) ? s : null;
        }

        /** The cue for an action, or null when it is silent. */
        static String resolve(SlideTextData.Action a) {
            return a == null ? null : resolve(a.sound, a.isMove());
        }

        // ---- playback / export -------------------------------------------------

        private static final java.util.Map<String, byte[]> CACHE = new java.util.HashMap<>();

        private static synchronized byte[] pcm(String name) {
            byte[] c = CACHE.get(name);
            if (c == null) {
                c = render(name);
                CACHE.put(name, c);
            }
            return c;
        }

        /** Fire-and-forget: opens a fresh Clip, plays, and closes itself on stop.
         *  A null / unknown name plays nothing; an audio failure (no mixer, say)
         *  falls back to the system beep. */
        static void play(String name) {
            if (name == null || NONE.equals(name) || !isBuiltIn(name)) return;
            try {
                byte[] buf = pcm(name);
                javax.sound.sampled.Clip clip = javax.sound.sampled.AudioSystem.getClip();
                clip.open(FORMAT, buf, 0, buf.length);
                clip.addLineListener(ev -> {
                    if (ev.getType() == javax.sound.sampled.LineEvent.Type.STOP) {
                        ev.getLine().close();
                    }
                });
                clip.start();
            } catch (Exception ignored) {
                java.awt.Toolkit.getDefaultToolkit().beep();
            }
        }

        /** Write a cue as a WAV file (for muxing into an exported video with
         *  ffmpeg). One file per cue name, reused when it already exists. */
        static File writeWav(File dir, String name) throws IOException {
            byte[] buf = pcm(name);
            File f = new File(dir, "motion_" + name.toLowerCase(java.util.Locale.US)
                    .replaceAll("[^a-z0-9]+", "_") + ".wav");
            if (f.isFile() && f.length() > 0) return f;
            try (javax.sound.sampled.AudioInputStream ais = new javax.sound.sampled.AudioInputStream(
                    new java.io.ByteArrayInputStream(buf), FORMAT, buf.length / FORMAT.getFrameSize())) {
                javax.sound.sampled.AudioSystem.write(ais,
                        javax.sound.sampled.AudioFileFormat.Type.WAVE, f);
            }
            return f;
        }

        // ---- synthesis ---------------------------------------------------------

        /** How long each cue runs, in seconds (the buffer is cut to fit). */
        private static double lengthOf(String name) {
            switch (name) {
                case "Whoosh":         return 0.32;
                case "Soft Swoosh":    return 0.50;
                case "Air Swipe":      return 0.26;
                case "Fast Sweep":     return 0.38;
                case "Reverse Swell":  return 0.70;
                case "Pop":            return 0.22;
                case "Click":          return 0.10;
                case "Snap":           return 0.16;
                case "Page Turn":      return 0.45;
                case "Typewriter":     return 0.30;
                case "Impact":         return 0.90;
                case "Sub Drop":       return 1.00;
                case "Riser":          return 0.75;
                case "Shimmer":        return 1.10;
                case "Magic Chime":    return 1.40;
                default:               return 0.40;
            }
        }

        private static byte[] render(String name) {
            if ("Whoosh".equals(name)) return whooshPcm();   // unchanged, note for note
            double[] buf = new double[(int) (SR * lengthOf(name))];
            switch (name) {
                case "Soft Swoosh":
                    // Air moving past: a dark-to-bright-to-dark noise arc with a
                    // breath of low tone under it. The gentlest of the movers.
                    addSweptNoise(buf, 0, 0.50, 0.34, 0.06, 0.34, 2.0);
                    addPartial(buf, 0, 0.50, 180, 90, 0.10, 5.0);
                    break;
                case "Air Swipe":
                    // Quick and bright — a hand passing the mic. For fast moves.
                    addSweptNoise(buf, 0, 0.26, 0.40, 0.30, 0.08, 1.4);
                    break;
                case "Fast Sweep":
                    // Bright noise sweeping down with a falling tone: the classic
                    // "flies in from off-screen" cue.
                    addSweptNoise(buf, 0, 0.38, 0.36, 0.40, 0.07, 1.2);
                    addPartial(buf, 0, 0.34, 1900, 380, 0.13, 7.0);
                    break;
                case "Reverse Swell":
                    // Backwards: quiet to loud, landing on the beat. Best on a
                    // move that arrives on a word.
                    addRevSweptNoise(buf, 0, 0.70, 0.34, 0.05, 0.30);
                    addPartial(buf, 0.34, 0.36, 240, 620, 0.12, 1.2);
                    break;
                case "Pop":
                    // Small, round, friendly — a bubble surfacing.
                    addPartial(buf, 0, 0.20, 420, 1350, 0.44, 26);
                    addNoise(buf, 0, 0.02, 0.13, 200);
                    break;
                case "Click":
                    // Tight UI click. Almost no tail, so it never muddies speech.
                    addNoise(buf, 0, 0.03, 0.48, 200);
                    addPartial(buf, 0, 0.05, 2600, 1700, 0.26, 90);
                    break;
                case "Snap":
                    // Finger snap: a crack of noise with a woody ring behind it.
                    addNoise(buf, 0, 0.05, 0.48, 130);
                    addPartial(buf, 0, 0.10, 1250, 900, 0.26, 55);
                    addPartial(buf, 0, 0.10, 2500, 1900, 0.12, 65);
                    break;
                case "Page Turn":
                    // Paper: two soft brushes of dark noise, one after the other.
                    addSweptNoise(buf, 0,     0.24, 0.26, 0.10, 0.22, 1.6);
                    addSweptNoise(buf, 0.16,  0.28, 0.20, 0.22, 0.08, 1.6);
                    break;
                case "Typewriter":
                    // Key strike then the carriage settling — mechanical, dry.
                    addNoise(buf, 0, 0.02, 0.48, 260);
                    addPartial(buf, 0, 0.07, 900, 520, 0.32, 70);
                    addPartial(buf, 0.02, 0.09, 240, 180, 0.24, 45);
                    addNoise(buf, 0.11, 0.02, 0.17, 240);
                    break;
                case "Impact":
                    // Cinematic hit: a low body, a mid knock and a short tail.
                    addPartial(buf, 0, 0.80, 95, 52, 0.42, 5.0);
                    addPartial(buf, 0, 0.40, 190, 120, 0.18, 9.0);
                    addNoise(buf, 0, 0.14, 0.26, 34);
                    break;
                case "Sub Drop":
                    // Deep falling sub — weight under a big move. Mind the volume
                    // on small speakers; it is felt more than heard.
                    addPartial(buf, 0, 1.00, 150, 34, 0.46, 3.0);
                    addPartial(buf, 0, 0.55, 300, 70, 0.12, 5.0);
                    break;
                case "Riser":
                    // Tension climbing into the landing: noise opening up under a
                    // rising tone, both cut at the top.
                    addRevSweptNoise(buf, 0, 0.75, 0.30, 0.06, 0.40);
                    addPartial(buf, 0, 0.72, 220, 1250, 0.16, 0.6);
                    break;
                case "Shimmer":
                    // Sparkle: a spray of high partials, each a moment later, so it
                    // glitters instead of ringing like a bell.
                    addPartial(buf, 0.00, 0.90, 2093, 2093, 0.20, 5.0);
                    addPartial(buf, 0.06, 0.90, 2637, 2637, 0.17, 5.4);
                    addPartial(buf, 0.13, 0.90, 3136, 3136, 0.14, 5.8);
                    addPartial(buf, 0.21, 0.85, 4186, 4186, 0.10, 6.4);
                    addNoise(buf, 0, 0.04, 0.07, 90);
                    break;
                case "Magic Chime":
                    // A clean major triad with a bell's decay — the "it landed and
                    // it matters" cue.
                    addPartial(buf, 0.00, 1.30, 1046, 1046, 0.26, 3.2);
                    addPartial(buf, 0.08, 1.25, 1318, 1318, 0.19, 3.4);
                    addPartial(buf, 0.16, 1.20, 1568, 1568, 0.15, 3.6);
                    addPartial(buf, 0.16, 1.20, 3136, 3136, 0.05, 4.6);
                    break;
                default:
                    addPartial(buf, 0, 0.30, 900, 500, 0.24, 12);
                    break;
            }
            return quantize(buf);
        }

        /** The original whoosh, kept exactly as it was so every project made
         *  before the sound picker still sounds the way it did. */
        private static byte[] whooshPcm() {
            final int sr = 44100;
            final double durSec = 0.32;
            final int n = (int) (sr * durSec);
            byte[] buf = new byte[n * 2];
            for (int i = 0; i < n; i++) {
                double t = i / (double) sr;
                double p = t / durSec;                          // 0..1 through the sound
                double f = 320 + 900 * Math.sin(Math.PI * p);   // pitch rises then falls
                double env = Math.sin(Math.PI * p);             // soft attack + decay
                env *= env;
                double s = Math.sin(2 * Math.PI * f * t)
                         + 0.35 * Math.sin(2 * Math.PI * f * 2 * t);   // add a partial
                s += 0.15 * (Math.random() * 2 - 1) * (1 - p);        // a breath of air
                int v = (int) (Math.max(-1, Math.min(1, s / 1.5)) * env * 32767 * 0.7);
                buf[i * 2]     = (byte) (v & 0xFF);
                buf[i * 2 + 1] = (byte) ((v >> 8) & 0xFF);
            }
            return buf;
        }

        /** Float buffer → 16-bit mono PCM, soft-clipped so stacked layers in a
         *  cue never crackle. */
        private static byte[] quantize(double[] buf) {
            byte[] out = new byte[buf.length * 2];
            for (int i = 0; i < buf.length; i++) {
                int s = (int) Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE,
                        Math.tanh(buf[i] * 1.15) * 32000));
                out[i * 2]     = (byte) (s & 0xFF);
                out[i * 2 + 1] = (byte) ((s >> 8) & 0xFF);
            }
            return out;
        }

        private static void mix(double[] buf, int at, double v) {
            if (at >= 0 && at < buf.length) buf[at] += v;
        }

        /** Damped sine partial: amp · e^(−decay·t) · sin(2πf t), swept to {@code f2}. */
        private static void addPartial(double[] buf, double atSec, double durSec,
                                       double f, double f2, double amp, double decay) {
            int start = (int) (atSec * SR);
            int n = (int) (durSec * SR);
            double phase = 0;
            for (int i = 0; i < n; i++) {
                double p = i / (double) n;
                phase += 2 * Math.PI * (f + (f2 - f) * p) / SR;
                double env = Math.exp(-decay * (i / SR));
                double fin = Math.min(1, i / (SR * 0.004));   // 4 ms fade-in kills the click
                mix(buf, start + i, Math.sin(phase) * amp * env * fin);
            }
        }

        /** Short filtered-noise burst — the body of clicks, snaps and impacts. */
        private static void addNoise(double[] buf, double atSec, double durSec,
                                     double amp, double decay) {
            int start = (int) (atSec * SR);
            int n = (int) (durSec * SR);
            double last = 0;
            for (int i = 0; i < n; i++) {
                last = last * 0.55 + (Math.random() * 2 - 1) * 0.45;   // gentle low-pass
                mix(buf, start + i, last * amp * Math.exp(-decay * (i / SR)));
            }
        }

        /** Noise whose brightness travels over its length — the body of every
         *  swoosh. {@code k0}/{@code k1} are one-pole coefficients (small = dark,
         *  large = bright); {@code shape} sharpens the sin() amplitude arc. The
         *  1/√k term keeps a dark filter from swallowing the level. */
        private static void addSweptNoise(double[] buf, double atSec, double durSec,
                                          double amp, double k0, double k1, double shape) {
            int start = (int) (atSec * SR);
            int n = (int) (durSec * SR);
            double last = 0;
            for (int i = 0; i < n; i++) {
                double p = i / (double) n;
                double k = Math.max(0.02, k0 + (k1 - k0) * p);
                last = last * (1 - k) + (Math.random() * 2 - 1) * k;
                double env = Math.pow(Math.sin(Math.PI * p), shape);
                mix(buf, start + i, last * amp * env / Math.sqrt(k));
            }
        }

        /** Swept noise that swells instead of arcing — silence to full at the very
         *  end, for the reverse and riser cues. */
        private static void addRevSweptNoise(double[] buf, double atSec, double durSec,
                                             double amp, double k0, double k1) {
            int start = (int) (atSec * SR);
            int n = (int) (durSec * SR);
            double last = 0;
            for (int i = 0; i < n; i++) {
                double p = i / (double) n;
                double k = Math.max(0.02, k0 + (k1 - k0) * p);
                last = last * (1 - k) + (Math.random() * 2 - 1) * k;
                double env = p * p;                       // swells toward the landing
                if (p > 0.94) env *= (1 - p) / 0.06;      // then stops dead
                mix(buf, start + i, last * amp * env / Math.sqrt(k));
            }
        }
    }

    static class WordTiming {
        final String word;
        final double startSec;
        final double endSec;
        WordTiming(String word, double startSec, double endSec) {
            this.word = word == null ? "" : word;
            this.startSec = startSec;
            this.endSec = endSec;
        }
    }

    /** Persistent on-disk format for a list of word timings, stored as a `.timings`
     *  sidecar next to the audio file. One line per word: `start|end|word`.
     *  Pipes are used (instead of JSON) so the file is human-grep-able and the
     *  parser is one line of Java. Spaces inside the word are preserved. */
    static class WordTimingFile {
        static List<WordTiming> readSidecar(File audioFile) {
            if (audioFile == null) return null;
            File side = sidecarFor(audioFile);
            if (!side.isFile()) return null;
            List<WordTiming> out = new ArrayList<>();
            try (BufferedReader r = new BufferedReader(new java.io.FileReader(side, java.nio.charset.StandardCharsets.UTF_8))) {
                String line;
                while ((line = r.readLine()) != null) {
                    if (line.isEmpty()) continue;
                    String[] parts = line.split("\\|", 3);
                    if (parts.length != 3) continue;
                    try {
                        double s = Double.parseDouble(parts[0]);
                        double e = Double.parseDouble(parts[1]);
                        out.add(new WordTiming(parts[2], s, e));
                    } catch (NumberFormatException ignored) {}
                }
            } catch (IOException e) {
                return null;
            }
            return out.isEmpty() ? null : out;
        }
        static void writeSidecar(File audioFile, List<WordTiming> timings) throws IOException {
            File side = sidecarFor(audioFile);
            try (java.io.Writer w = new java.io.OutputStreamWriter(
                    new java.io.FileOutputStream(side), java.nio.charset.StandardCharsets.UTF_8)) {
                for (WordTiming t : timings) {
                    w.write(String.format(java.util.Locale.US, "%.3f|%.3f|%s%n",
                            t.startSec, t.endSec, t.word.replace("\r", "").replace("\n", " ")));
                }
            }
        }
        static File sidecarFor(File audioFile) {
            return new File(audioFile.getParentFile(),
                    audioFile.getName() + ".timings");
        }
    }

    /** Re-bucket Scribe's raw word timings so index i corresponds to the i-th
     *  whitespace-separated token of the hint text — which is exactly what the
     *  renderer's computeWordIndexSegment counts. Scribe's tokenization diverges
     *  from the visible text in two routine ways: it splits contractions
     *  ("it's" → "it" + "'s"), emits punctuation as its own word entry, and may
     *  include audio-event entries; conversely it can also drop words it didn't
     *  hear. Either way the bare Scribe index points at the wrong visible word
     *  and the highlight appears to skip. We walk both streams of letter/digit
     *  characters in parallel, attributing each Scribe entry's [start, end] to
     *  the visible token its chars land on. A resync over chars Scribe didn't
     *  transcribe may only stop at the START of a later token (or back inside a
     *  token this entry has already matched), so an entry can never be credited
     *  to a word on the strength of one shared letter; and an entry that really
     *  does span two tokens is split between them by matched-character count.
     *  Both rules exist so that no two tokens can come out with the SAME window
     *  — a tie the karaoke pass breaks in favour of the earlier word, leaving
     *  the later one unreachable and its highlight never drawn. Visible tokens with no matched
     *  Scribe chars (e.g., a word Scribe missed, or punctuation-only tokens)
     *  inherit a window interpolated from their neighbours so the highlight
     *  still passes through. If the hint and Scribe diverge too far for the
     *  alignment to be meaningful, the original timings are returned unchanged.
     */
    static List<WordTiming> alignTimingsToText(List<WordTiming> scribe, String hintText) {
        if (scribe == null || scribe.isEmpty() || hintText == null) return scribe;
        String trimmed = hintText.trim();
        if (trimmed.isEmpty()) return scribe;
        String[] tokens = trimmed.split("\\s+");

        String[] tnorm = new String[tokens.length];
        int totalChars = 0;
        for (int i = 0; i < tokens.length; i++) {
            tnorm[i] = normalizeWordForAlign(tokens[i]);
            totalChars += tnorm[i].length();
        }
        if (totalChars == 0) return scribe;

        int[] charToToken = new int[totalChars];
        int[] tokStart = new int[tokens.length];
        StringBuilder hintNormBuf = new StringBuilder(totalChars);
        int p = 0;
        for (int i = 0; i < tokens.length; i++) {
            tokStart[i] = p;
            for (int k = 0; k < tnorm[i].length(); k++) charToToken[p + k] = i;
            hintNormBuf.append(tnorm[i]);
            p += tnorm[i].length();
        }
        String hintNorm = hintNormBuf.toString();

        double[] minStart = new double[tokens.length];
        double[] maxEnd   = new double[tokens.length];
        java.util.Arrays.fill(minStart, Double.POSITIVE_INFINITY);
        java.util.Arrays.fill(maxEnd,   Double.NEGATIVE_INFINITY);

        int hintPos = 0;
        int matchedChars = 0;
        final int LOOK_AHEAD = 8;
        for (WordTiming sw : scribe) {
            if (sw == null) continue;
            String w = normalizeWordForAlign(sw.word);
            if (w.isEmpty()) continue;
            int wi = 0;
            int openTok = -1;                 // token this entry is already inside
            // Chars this entry matched, per visible token, in stream order. An entry
            // that legitimately spans two tokens shares its window out between them
            // (below) rather than stamping the whole span onto each.
            java.util.List<int[]> hits = new java.util.ArrayList<>();
            while (wi < w.length() && hintPos < hintNorm.length()) {
                if (hintNorm.charAt(hintPos) == w.charAt(wi)) {
                    int tok = charToToken[hintPos];
                    if (hits.isEmpty() || hits.get(hits.size() - 1)[0] != tok) {
                        hits.add(new int[] { tok, 0 });
                    }
                    hits.get(hits.size() - 1)[1]++;
                    openTok = tok;
                    hintPos++; wi++;
                    matchedChars++;
                } else {
                    int max = Math.min(LOOK_AHEAD, hintNorm.length() - hintPos);
                    int look = 1;
                    boolean found = false;
                    for (; look < max; look++) {
                        int at = hintPos + look;
                        if (hintNorm.charAt(at) != w.charAt(wi)) continue;
                        // Resync only onto the START of a later word, or back into a
                        // word this entry is already inside. Landing part-way into a
                        // word this entry has matched nothing of would hand that word
                        // the entry's timing on the strength of one shared letter —
                        // the trailing "y" of "eighty" catching the "y" of "years",
                        // which gave both words one identical window.
                        int tok = charToToken[at];
                        if (at == tokStart[tok] || tok == openTok) { found = true; break; }
                    }
                    if (found) hintPos += look;   // skip hint chars Scribe didn't transcribe
                    else wi++;                    // skip Scribe char hint doesn't have
                }
            }
            // Attribute the entry. One token takes the whole [start, end]; a genuine
            // multi-token entry (Scribe returning "eighty-years" as one word) is split
            // across its tokens in proportion to the characters each one matched, so
            // no two tokens can come out of a single entry with the same window.
            int totalHit = 0;
            for (int[] h : hits) totalHit += h[1];
            if (totalHit > 0) {
                double span = Math.max(0, sw.endSec - sw.startSec);
                double acc = 0;
                for (int[] h : hits) {
                    double hs = sw.startSec + span * (acc / totalHit);
                    acc += h[1];
                    double he = sw.startSec + span * (acc / totalHit);
                    if (hs < minStart[h[0]]) minStart[h[0]] = hs;
                    if (he > maxEnd[h[0]])   maxEnd[h[0]]   = he;
                }
            }
        }

        if (matchedChars < Math.max(1, hintNorm.length() / 4)) return scribe;

        // Fill in the tokens Scribe matched nothing against. They arrive in runs,
        // and where a run sits decides what it means:
        //   • between two spoken tokens — words Scribe misheard or skipped. Share
        //     the gap out evenly so the highlight walks through them instead of
        //     jumping the whole run in one instant.
        //   • before the first or after the last spoken token — text the narration
        //     never says at all: a heading above the quote, the "~ Author, Title"
        //     attribution below it. These get an EMPTY window (end == start), which
        //     is how a token says "never spoken"; the karaoke pass skips them, so
        //     the box stops on the last word actually read out. Handing them a real
        //     window is what used to fling the box onto the very last word of the
        //     text the moment the narration ended.
        double[] outS = new double[tokens.length];
        double[] outE = new double[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            if (minStart[i] != Double.POSITIVE_INFINITY) {
                outS[i] = minStart[i];
                outE[i] = Math.max(maxEnd[i], minStart[i] + 0.05);
                continue;
            }
            int runEnd = i;
            while (runEnd + 1 < tokens.length && minStart[runEnd + 1] == Double.POSITIVE_INFINITY) runEnd++;
            // The token before a maximal run is always a matched one, so it is filled.
            double prev = i > 0 ? outE[i - 1] : Double.NEGATIVE_INFINITY;
            double next = Double.POSITIVE_INFINITY;
            for (int j = runEnd + 1; j < tokens.length; j++)
                if (minStart[j] != Double.POSITIVE_INFINITY) { next = minStart[j]; break; }
            int len = runEnd - i + 1;
            if (prev != Double.NEGATIVE_INFINITY && next != Double.POSITIVE_INFINITY && next > prev) {
                double step = (next - prev) / len;
                for (int k = 0; k < len; k++) {
                    outS[i + k] = prev + step * k;
                    outE[i + k] = prev + step * (k + 1);
                }
            } else {
                double at = prev != Double.NEGATIVE_INFINITY ? prev
                        : (next != Double.POSITIVE_INFINITY ? Math.max(0, next) : 0);
                for (int k = 0; k < len; k++) { outS[i + k] = at; outE[i + k] = at; }
            }
            i = runEnd;
        }

        List<WordTiming> out = new ArrayList<>(tokens.length);
        for (int i = 0; i < tokens.length; i++) out.add(new WordTiming(tokens[i], outS[i], outE[i]));
        return out;
    }

    /**
     * Index of the last word the narration actually speaks, or -1 when none does.
     *
     * <p>Two things mark a token as never spoken. An EMPTY window (end &lt;= start)
     * is what {@link #alignTimingsToText} writes for text outside the narration.
     * And in sidecars captured before it did that, such text instead carries a run
     * of trailing entries that all share ONE start time — the old fallback stamped
     * the end of the last spoken word onto every one of them. No real transcript
     * starts several consecutive words at the same instant, so that run reads the
     * same way here and old .timings files need no re-sync.
     */
    static int lastSpokenTimingIndex(List<WordTiming> timings) {
        if (timings == null || timings.isEmpty()) return -1;
        int last = -1;
        for (int i = 0; i < timings.size(); i++) {
            WordTiming wt = timings.get(i);
            if (wt != null && wt.endSec > wt.startSec) last = i;
        }
        if (last <= 0) return last;
        int runStart = last;
        while (runStart > 0) {
            WordTiming a = timings.get(runStart - 1), b = timings.get(runStart);
            if (a == null || b == null || a.startSec != b.startSec) break;
            runStart--;
        }
        return runStart == last ? last : runStart - 1;
    }

    private static String normalizeWordForAlign(String s) {
        if (s == null) return "";
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLetterOrDigit(c)) sb.append(Character.toLowerCase(c));
        }
        return sb.toString();
    }

    // ==================== ElevenLabs Scribe (Speech-to-Text) ====================
    /**
     * Calls the ElevenLabs Scribe API to get per-word timestamps for an audio
     * file. The user's typed text is sent as a hint via the `prompt` field —
     * Scribe biases its decoding toward those words, which is what makes the
     * timings line up with the rendered text instead of an alternate
     * transcription. API key is read from `ELEVENLABS_API_KEY` env var or
     * `~/.gifslideshow/elevenlabs.key`; if neither is set we surface a clear
     * IOException so the caller can prompt the user.
     */
    static class ElevenLabsScribe {
        private static final String ENDPOINT = "https://api.elevenlabs.io/v1/speech-to-text";

        static String resolveApiKey() {
            String env = System.getenv("ELEVENLABS_API_KEY");
            if (env != null && !env.isBlank()) return env.trim();
            File f = new File(System.getProperty("user.home"), ".gifslideshow/elevenlabs.key");
            if (f.isFile()) {
                try {
                    String s = new String(java.nio.file.Files.readAllBytes(f.toPath()),
                            java.nio.charset.StandardCharsets.UTF_8).trim();
                    if (!s.isEmpty()) return s;
                } catch (IOException ignored) {}
            }
            return null;
        }

        static void saveApiKey(String key) throws IOException {
            File dir = new File(System.getProperty("user.home"), ".gifslideshow");
            dir.mkdirs();
            File f = new File(dir, "elevenlabs.key");
            try (java.io.Writer w = new java.io.OutputStreamWriter(
                    new java.io.FileOutputStream(f), java.nio.charset.StandardCharsets.UTF_8)) {
                w.write(key.trim());
            }
            try { java.nio.file.Files.setPosixFilePermissions(f.toPath(),
                    java.util.EnumSet.of(java.nio.file.attribute.PosixFilePermission.OWNER_READ,
                            java.nio.file.attribute.PosixFilePermission.OWNER_WRITE)); } catch (Exception ignored) {}
        }

        /** Detect language code from text content. Returns "ara" for any text containing
         *  Arabic script, otherwise "eng". Scribe accepts ISO-639-3 codes. */
        static String detectLanguage(String text) {
            if (text == null) return "eng";
            for (int i = 0; i < text.length(); i++) {
                int cp = text.codePointAt(i);
                if ((cp >= 0x0600 && cp <= 0x06FF)
                        || (cp >= 0x0750 && cp <= 0x077F)
                        || (cp >= 0xFB50 && cp <= 0xFDFF)
                        || (cp >= 0xFE70 && cp <= 0xFEFF)) return "ara";
            }
            return "eng";
        }

        /** Strip punctuation + Arabic tashkeel so source-word matching is robust.
         *  Mirrors the cleaning done in the user's working Node script. */
        static String cleanWord(String raw) {
            if (raw == null) return "";
            String s = raw.trim();
            s = s.replaceAll("[\\p{P}\\p{S}]", "");
            s = s.replaceAll("[\\u064B-\\u0652\\u0670]", "");
            return s;
        }

        static List<WordTiming> transcribe(File audioFile, String hintText, String languageCode) throws IOException, InterruptedException {
            String apiKey = resolveApiKey();
            if (apiKey == null) {
                throw new IOException("No ElevenLabs API key. Set ELEVENLABS_API_KEY env var or ~/.gifslideshow/elevenlabs.key");
            }
            String boundary = "----GifSlideShowBoundary" + System.currentTimeMillis();
            byte[] body = buildMultipartBody(audioFile, hintText, languageCode, boundary);

            java.net.http.HttpClient http = java.net.http.HttpClient.newBuilder()
                    .connectTimeout(java.time.Duration.ofSeconds(15))
                    .build();
            java.net.http.HttpRequest req = java.net.http.HttpRequest.newBuilder()
                    .uri(java.net.URI.create(ENDPOINT))
                    .timeout(java.time.Duration.ofMinutes(5))
                    .header("xi-api-key", apiKey)
                    .header("Content-Type", "multipart/form-data; boundary=" + boundary)
                    .POST(java.net.http.HttpRequest.BodyPublishers.ofByteArray(body))
                    .build();
            java.net.http.HttpResponse<String> resp = http.send(req,
                    java.net.http.HttpResponse.BodyHandlers.ofString(java.nio.charset.StandardCharsets.UTF_8));
            if (resp.statusCode() / 100 != 2) {
                throw new IOException("ElevenLabs Scribe HTTP " + resp.statusCode() + ": "
                        + truncate(resp.body(), 500));
            }
            return parseWords(resp.body());
        }

        private static byte[] buildMultipartBody(File audioFile, String hintText, String languageCode, String boundary) throws IOException {
            java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
            byte[] audio = java.nio.file.Files.readAllBytes(audioFile.toPath());
            String dash = "--";
            String crlf = "\r\n";
            String name = audioFile.getName();
            String mime = guessAudioMime(name);

            appendUtf8(out, dash + boundary + crlf);
            appendUtf8(out, "Content-Disposition: form-data; name=\"model_id\"" + crlf + crlf + "scribe_v1" + crlf);

            appendUtf8(out, dash + boundary + crlf);
            appendUtf8(out, "Content-Disposition: form-data; name=\"language_code\"" + crlf + crlf + (languageCode == null ? "eng" : languageCode) + crlf);

            appendUtf8(out, dash + boundary + crlf);
            appendUtf8(out, "Content-Disposition: form-data; name=\"timestamps_granularity\"" + crlf + crlf + "word" + crlf);

            if (hintText != null && !hintText.isBlank()) {
                appendUtf8(out, dash + boundary + crlf);
                appendUtf8(out, "Content-Disposition: form-data; name=\"prompt\"" + crlf
                        + "Content-Type: text/plain; charset=UTF-8" + crlf + crlf + hintText + crlf);
            }

            appendUtf8(out, dash + boundary + crlf);
            appendUtf8(out, "Content-Disposition: form-data; name=\"file\"; filename=\"" + name + "\"" + crlf);
            appendUtf8(out, "Content-Type: " + mime + crlf + crlf);
            out.write(audio);
            appendUtf8(out, crlf);

            appendUtf8(out, dash + boundary + dash + crlf);
            return out.toByteArray();
        }

        private static void appendUtf8(java.io.ByteArrayOutputStream out, String s) throws IOException {
            out.write(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }

        private static String guessAudioMime(String name) {
            String n = name.toLowerCase();
            if (n.endsWith(".mp3")) return "audio/mpeg";
            if (n.endsWith(".wav")) return "audio/wav";
            if (n.endsWith(".m4a") || n.endsWith(".mp4") || n.endsWith(".aac")) return "audio/mp4";
            if (n.endsWith(".ogg") || n.endsWith(".oga")) return "audio/ogg";
            if (n.endsWith(".flac")) return "audio/flac";
            if (n.endsWith(".webm")) return "audio/webm";
            return "application/octet-stream";
        }

        private static String truncate(String s, int n) {
            if (s == null) return "";
            return s.length() <= n ? s : s.substring(0, n) + "…";
        }

        /** Minimal JSON parser for the Scribe response shape we care about:
         *  `{"words":[{"text":"hello","type":"word","start":0.12,"end":0.41}, ...]}`.
         *  Pulls each word entry's text/start/end via regex — keeps us off a
         *  full JSON library dependency for one endpoint. Skips entries whose
         *  `type` is "spacing" (Scribe's word for the gaps between words). */
        static List<WordTiming> parseWords(String json) {
            List<WordTiming> out = new ArrayList<>();
            if (json == null) return out;
            int wordsStart = json.indexOf("\"words\"");
            if (wordsStart < 0) return out;
            int arrStart = json.indexOf('[', wordsStart);
            if (arrStart < 0) return out;
            int depth = 0;
            int objStart = -1;
            for (int i = arrStart; i < json.length(); i++) {
                char c = json.charAt(i);
                if (c == '[') depth++;
                else if (c == ']') { depth--; if (depth == 0) break; }
                else if (c == '{' && depth == 1 && objStart < 0) objStart = i;
                else if (c == '}' && depth == 1 && objStart >= 0) {
                    String obj = json.substring(objStart, i + 1);
                    objStart = -1;
                    String type = extractJsonString(obj, "type");
                    if (type != null && type.equals("spacing")) continue;
                    String text = extractJsonString(obj, "text");
                    if (text == null) text = extractJsonString(obj, "word");
                    Double s = extractJsonNumber(obj, "start");
                    Double e = extractJsonNumber(obj, "end");
                    if (text != null && s != null && e != null) {
                        out.add(new WordTiming(text, s, e));
                    }
                }
            }
            return out;
        }

        private static String extractJsonString(String obj, String key) {
            String needle = "\"" + key + "\"";
            int k = obj.indexOf(needle);
            if (k < 0) return null;
            int colon = obj.indexOf(':', k + needle.length());
            if (colon < 0) return null;
            int i = colon + 1;
            while (i < obj.length() && Character.isWhitespace(obj.charAt(i))) i++;
            if (i >= obj.length() || obj.charAt(i) != '"') return null;
            i++;
            StringBuilder sb = new StringBuilder();
            while (i < obj.length()) {
                char c = obj.charAt(i);
                if (c == '\\' && i + 1 < obj.length()) {
                    char n = obj.charAt(i + 1);
                    switch (n) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'n': sb.append('\n'); break;
                        case 't': sb.append('\t'); break;
                        case 'r': sb.append('\r'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'u':
                            if (i + 5 < obj.length()) {
                                try { sb.append((char) Integer.parseInt(obj.substring(i + 2, i + 6), 16)); } catch (Exception ignored) {}
                                i += 4;
                            }
                            break;
                        default: sb.append(n);
                    }
                    i += 2;
                } else if (c == '"') {
                    return sb.toString();
                } else {
                    sb.append(c);
                    i++;
                }
            }
            return null;
        }

        private static Double extractJsonNumber(String obj, String key) {
            String needle = "\"" + key + "\"";
            int k = obj.indexOf(needle);
            if (k < 0) return null;
            int colon = obj.indexOf(':', k + needle.length());
            if (colon < 0) return null;
            int i = colon + 1;
            while (i < obj.length() && Character.isWhitespace(obj.charAt(i))) i++;
            int start = i;
            while (i < obj.length()) {
                char c = obj.charAt(i);
                if ((c >= '0' && c <= '9') || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+') i++;
                else break;
            }
            if (i == start) return null;
            try { return Double.parseDouble(obj.substring(start, i)); } catch (NumberFormatException e) { return null; }
        }
    }

    // ==================== SlideData ====================

    private static class SlideData {
        final BufferedImage image;
        final String text;
        final String fontName;
        final int fontSize;
        final int fontStyle;
        final Color fontColor;
        final int alignment;
        final boolean showPin;
        final String displayMode;
        final int subtitleY;
        final int subtitleBgOpacity;
        final boolean showSlideNumber;
        final String slideNumberText;
        final String slideNumberFontName;
        final int slideNumberX;
        final int slideNumberY;
        final int slideNumberSize;
        final Color slideNumberColor;
        // Set externally after construction (like quiz) so we don't have to
        // thread two more args through the SlideData constructor.
        String slideNumberStyle = "Circle";
        String slideNumberEffect = "None";
        final List<SlideTextData> slideTexts;
        final List<SlidePictureData> slidePictures;
        final boolean fxRoundCorners;
        final int fxCornerRadius;
        final int fxVignette;
        final int fxSepia;
        final int fxGrain;
        final int fxWaterRipple;
        final int fxGlitch;
        final int fxShake;
        final int fxScanline;
        final int fxRaised;
        final String fxOtherKind;
        final int fxOther;
        final boolean overlayEnabled;
        final String overlayShape;
        final String overlayBgMode;
        final Color overlayBgColor;
        final int overlayX;
        final int overlayY;
        final int overlaySize;
        final boolean textJustify;
        final int textWidthPct;
        final String highlightText;
        final Color highlightColor;
        final int textShiftX;
        final List<File> audioFiles;
        final List<Integer> audioDurationsMs;
        final int audioGapMs;
        // Per-text-row audio highlight settings, parallel to audioFiles.
        // Index N applies when the audio at audioFiles.get(N) is active.
        final List<Color> audioHlColor;
        final List<String> audioHlEffects;
        final List<Integer> audioGlowSize;
        final int totalAudioDurationMs;
        final File videoOverlayFile;
        final int videoOverlayX;
        final int videoOverlayY;
        final int videoOverlaySize;
        final int videoOverlayDurationMs;
        final boolean videoOverlayFill;
        final boolean videoOverlayBehind;
        // Independent "this slide IS a video" source (separate from the overlay toolbar).
        final File sourceVideoFile;
        final int sourceVideoDurationMs;
        // Source-video audio volume as a 0..100 percentage. Default 25 matches the
        // legacy hardcoded -0.25 attenuation so existing exports stay byte-identical.
        int sourceVideoVolume = 25;
        // Background transparency 0..100. 0 = BG fully opaque (current behavior),
        // 100 = BG fully transparent (only base color shows). Set externally
        // like sourceVideoVolume to avoid threading another arg through the ctor.
        int bgTransparency = 0;
        // Per-text-row word timings, parallel to audioFiles. Index N applies when
        // audioFiles.get(N) is playing — produced by ElevenLabs Scribe via the
        // "🎤 Word Sync" toolbar button. Null entries (or null list) mean that
        // text row has no per-word highlighting; the renderer falls back to its
        // existing whole-text highlight behavior.
        List<List<WordTiming>> audioWordTimings;
        // Per-text-row karaoke effect style + color (toolbar 7d). Parallel to
        // audioFiles. Independent of audioHl* — the karaoke post-pass reads
        // these regardless of what the existing audio-HL FX are doing.
        List<String> audioKaraokeStyle;
        List<Color>  audioKaraokeColor;
        // Per-text-row karaoke effect intensity + tightness (toolbar 7d), 1..10.
        List<Integer> audioKaraokeIntensity;
        List<Integer> audioKaraokeTight;
        // Quiz config snapshot (timer + reveal). Set externally after construction
        // so we don't have to thread another arg through the giant ctor.
        QuizSlide quiz;
        // Animated vector annotations (Lines / Arrows). Set externally after
        // construction (like quiz) so no arg is threaded through the giant ctor.
        // Composited per-frame by paintAnnotationsOverlay(...).
        List<SlideAnnotation> slideAnnotations = new ArrayList<>();
        // On-slide countdown timer (the "⏳ Slide Timer" toolbar button). Set
        // externally after construction like quiz/slideAnnotations, together with
        // the slide-relative moment its schedule resolves to.
        SlideTimer slideTimer;
        int slideTimerStartMs;
        /** Length of the timer's "play this when it finishes" file, ms (0 = none). */
        int slideTimerEndAudioMs;
        // Video "repeat part" ranges — each entry is {startMs, endMs} (relative to
        // the start of this slide). During export the finished, fully-composited
        // slide video has each range duplicated back-to-back so that part plays
        // twice. Set externally after construction (like sourceVideoVolume).
        List<int[]> videoRepeats;
        // When true, short (~12ms) audio fades are applied at each repeat seam so
        // the loop-back does not click. Duration is preserved (fades ramp
        // amplitude only), so audio stays in sync with the clean video cut.
        // On by default: a click at a loop-back is not something anyone asks
        // for, and `slow` is optional, so a plain "start,end" range must come out
        // clean with nothing else configured. Untick it only to keep the repeated
        // audio bit-exact.
        boolean videoRepeatCrossfade = true;
        // Slow the WHOLE finished video by this percent (100 = normal speed,
        // 150 = 1.5× slower, …). Applied as a final pitch-preserving pass on the
        // exported MP4. Set externally after construction (like videoRepeats).
        int videoGlobalSlowPct = 100;

        SlideData(BufferedImage image, String text, String fontName, int fontSize,
                  int fontStyle, Color fontColor, int alignment, boolean showPin, String displayMode,
                  int subtitleY, int subtitleBgOpacity,
                  boolean showSlideNumber, String slideNumberText, String slideNumberFontName,
                  int slideNumberX, int slideNumberY,
                  int slideNumberSize, Color slideNumberColor,
                  List<SlideTextData> slideTexts,
                  List<SlidePictureData> slidePictures,
                  boolean fxRoundCorners, int fxCornerRadius,
                  int fxVignette, int fxSepia, int fxGrain,
                  int fxWaterRipple, int fxGlitch, int fxShake,
                  int fxScanline, int fxRaised,
                  String fxOtherKind, int fxOther,
                  boolean overlayEnabled,
                  String overlayShape, String overlayBgMode, Color overlayBgColor,
                  int overlayX, int overlayY, int overlaySize,
                  boolean textJustify, int textWidthPct,
                  String highlightText, Color highlightColor,
                  int textShiftX,
                  List<Integer> audioDurationsMs, List<File> audioFiles,
                  int audioGapMs,
                  List<Color> audioHlColor, List<String> audioHlEffects, List<Integer> audioGlowSize,
                  File videoOverlayFile, int videoOverlayX, int videoOverlayY,
                  int videoOverlaySize, int videoOverlayDurationMs,
                  boolean videoOverlayFill, boolean videoOverlayBehind,
                  File sourceVideoFile, int sourceVideoDurationMs) {
            this.image = image;
            this.text = text;
            this.fontName = fontName;
            this.fontSize = fontSize;
            this.fontStyle = fontStyle;
            this.fontColor = fontColor;
            this.alignment = alignment;
            this.showPin = showPin;
            this.displayMode = displayMode;
            this.subtitleY = subtitleY;
            this.subtitleBgOpacity = subtitleBgOpacity;
            this.showSlideNumber = showSlideNumber;
            this.slideNumberText = slideNumberText;
            this.slideNumberFontName = slideNumberFontName;
            this.slideNumberX = slideNumberX;
            this.slideNumberY = slideNumberY;
            this.slideNumberSize = slideNumberSize;
            this.slideNumberColor = slideNumberColor;
            this.slideTexts = slideTexts;
            this.slidePictures = slidePictures != null ? slidePictures : new ArrayList<>();
            this.fxRoundCorners = fxRoundCorners;
            this.fxCornerRadius = fxCornerRadius;
            this.fxVignette = fxVignette;
            this.fxSepia = fxSepia;
            this.fxGrain = fxGrain;
            this.fxWaterRipple = fxWaterRipple;
            this.fxGlitch = fxGlitch;
            this.fxShake = fxShake;
            this.fxScanline = fxScanline;
            this.fxRaised = fxRaised;
            this.fxOtherKind = fxOtherKind == null ? "None" : fxOtherKind;
            this.fxOther = fxOther;
            this.overlayEnabled = overlayEnabled;
            this.overlayShape = overlayShape;
            this.overlayBgMode = overlayBgMode;
            this.overlayBgColor = overlayBgColor;
            this.overlayX = overlayX;
            this.overlayY = overlayY;
            this.overlaySize = overlaySize;
            this.textJustify = textJustify;
            this.textWidthPct = textWidthPct;
            this.highlightText = highlightText;
            this.highlightColor = highlightColor;
            this.textShiftX = textShiftX;
            this.audioFiles = audioFiles != null ? audioFiles : new java.util.ArrayList<>();
            this.audioDurationsMs = audioDurationsMs != null ? audioDurationsMs : new java.util.ArrayList<>();
            this.audioGapMs = audioGapMs;
            this.audioHlColor = audioHlColor != null ? audioHlColor : new java.util.ArrayList<>();
            this.audioHlEffects = audioHlEffects != null ? audioHlEffects : new java.util.ArrayList<>();
            this.audioGlowSize = audioGlowSize != null ? audioGlowSize : new java.util.ArrayList<>();
            int totalMs = 0;
            int numValid = 0;
            for (int d : this.audioDurationsMs) { if (d > 0) { totalMs += d; numValid++; } }
            if (numValid > 1 && audioGapMs > 0) totalMs += (numValid - 1) * audioGapMs;
            this.totalAudioDurationMs = totalMs;
            this.videoOverlayFile = videoOverlayFile;
            this.videoOverlayX = videoOverlayX;
            this.videoOverlayY = videoOverlayY;
            this.videoOverlaySize = videoOverlaySize;
            this.videoOverlayDurationMs = videoOverlayDurationMs;
            this.videoOverlayFill = videoOverlayFill;
            this.videoOverlayBehind = videoOverlayBehind;
            this.sourceVideoFile = sourceVideoFile;
            this.sourceVideoDurationMs = sourceVideoDurationMs;
        }
    }

