            addSlideTextBtn.setFocusPainted(false);
            addSlideTextBtn.setToolTipText("Add another slide text overlay");
            addSlideTextBtn.addActionListener(e -> {
                saveCurrentSlideTextToItem();
                saveAudioHlForCurrentText();
                slideTextItems.add(new SlideTextData(false, "", loadedFontNames.length > 0 ? loadedFontNames[0] : "Segoe UI",
                        40, Font.PLAIN, Color.YELLOW, 50, 50, 0, Color.BLACK, false, 100, 0, SwingConstants.CENTER));
                int newIdx = slideTextItems.size() - 1;
                // Seed new text row's HL from text-row 0 (the master), so adding a
                // row mid-project inherits the existing project's highlight style.
                slideAudioHlEffectsMap.put(newIdx, slideAudioHlEffectsMap.getOrDefault(0, DEFAULT_AUDIO_HL_EFFECTS));
                slideAudioHlColorMap.put(newIdx, slideAudioHlColorMap.getOrDefault(0, DEFAULT_AUDIO_HL_COLOR));
                slideAudioHlGlowSizeMap.put(newIdx, slideAudioHlGlowSizeMap.getOrDefault(0, DEFAULT_AUDIO_GLOW_SIZE));
                currentSlideTextIndex = newIdx;
                isLoadingSlideText = true;
                try {
                    rebuildSlideTextSelector();
                    slideTextSelector.setSelectedIndex(currentSlideTextIndex);
                } finally {
                    isLoadingSlideText = false;
                }
                loadSlideTextFromItem(currentSlideTextIndex);
                loadAudioHlForCurrentText();
                onFormatChanged();
            });

            JButton removeSlideTextBtn = new JButton("\u2212");
            removeSlideTextBtn.setFont(new Font("Segoe UI", Font.BOLD, 12));
            removeSlideTextBtn.setPreferredSize(new Dimension(28, 24));
            removeSlideTextBtn.setFocusPainted(false);
            removeSlideTextBtn.setToolTipText("Remove current slide text overlay");
            removeSlideTextBtn.addActionListener(e -> {
                if (slideTextItems.size() <= 1) return;
                int removedIdx = currentSlideTextIndex;
                slideTextItems.remove(removedIdx);
                // Remove audio for the deleted text and shift higher indices down
                slideAudioFiles.remove(removedIdx);
                slideAudioDurationsMs.remove(removedIdx);
                slideAudioFiles2.remove(removedIdx);
                slideAudioDurationsMs2.remove(removedIdx);
                slideAudioHlEffectsMap.remove(removedIdx);
                slideAudioHlColorMap.remove(removedIdx);
                slideAudioHlGlowSizeMap.remove(removedIdx);
                slideAudioWordTimingsMap.remove(removedIdx);
                slideKaraokeStyleMap.remove(removedIdx);
                slideKaraokeColorMap.remove(removedIdx);
                slideKaraokeIntensityMap.remove(removedIdx);
                slideKaraokeTightMap.remove(removedIdx);
                java.util.Map<Integer, File> shiftedFiles = new java.util.HashMap<>();
                java.util.Map<Integer, Integer> shiftedDurations = new java.util.HashMap<>();
                java.util.Map<Integer, File> shiftedFiles2 = new java.util.HashMap<>();
                java.util.Map<Integer, Integer> shiftedDurations2 = new java.util.HashMap<>();
                java.util.Map<Integer, String>  shiftedHlEffects = new java.util.HashMap<>();
                java.util.Map<Integer, Color>   shiftedHlColor   = new java.util.HashMap<>();
                java.util.Map<Integer, Integer> shiftedHlGlow    = new java.util.HashMap<>();
                java.util.Map<Integer, List<WordTiming>> shiftedKaraokeTimings = new java.util.HashMap<>();
                java.util.Map<Integer, String> shiftedKaraokeStyle = new java.util.HashMap<>();
                java.util.Map<Integer, Color>  shiftedKaraokeColor = new java.util.HashMap<>();
                java.util.Map<Integer, Integer> shiftedKaraokeIntensity = new java.util.HashMap<>();
                java.util.Map<Integer, Integer> shiftedKaraokeTight     = new java.util.HashMap<>();
                for (java.util.Map.Entry<Integer, File> entry : slideAudioFiles.entrySet()) {
                    int key = entry.getKey();
                    shiftedFiles.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Integer> entry : slideAudioDurationsMs.entrySet()) {
                    int key = entry.getKey();
                    shiftedDurations.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, File> entry : slideAudioFiles2.entrySet()) {
                    int key = entry.getKey();
                    shiftedFiles2.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Integer> entry : slideAudioDurationsMs2.entrySet()) {
                    int key = entry.getKey();
                    shiftedDurations2.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, String> entry : slideAudioHlEffectsMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedHlEffects.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Color> entry : slideAudioHlColorMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedHlColor.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Integer> entry : slideAudioHlGlowSizeMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedHlGlow.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, List<WordTiming>> entry : slideAudioWordTimingsMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedKaraokeTimings.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, String> entry : slideKaraokeStyleMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedKaraokeStyle.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Color> entry : slideKaraokeColorMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedKaraokeColor.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Integer> entry : slideKaraokeIntensityMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedKaraokeIntensity.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                for (java.util.Map.Entry<Integer, Integer> entry : slideKaraokeTightMap.entrySet()) {
                    int key = entry.getKey();
                    shiftedKaraokeTight.put(key > removedIdx ? key - 1 : key, entry.getValue());
                }
                slideAudioFiles.clear();
                slideAudioFiles.putAll(shiftedFiles);
                slideAudioDurationsMs.clear();
                slideAudioDurationsMs.putAll(shiftedDurations);
                slideAudioFiles2.clear();
                slideAudioFiles2.putAll(shiftedFiles2);
                slideAudioDurationsMs2.clear();
                slideAudioDurationsMs2.putAll(shiftedDurations2);
                slideAudioHlEffectsMap.clear();
                slideAudioHlEffectsMap.putAll(shiftedHlEffects);
                slideAudioHlColorMap.clear();
                slideAudioHlColorMap.putAll(shiftedHlColor);
                slideAudioHlGlowSizeMap.clear();
                slideAudioHlGlowSizeMap.putAll(shiftedHlGlow);
                slideAudioWordTimingsMap.clear();
                slideAudioWordTimingsMap.putAll(shiftedKaraokeTimings);
                slideKaraokeStyleMap.clear();
                slideKaraokeStyleMap.putAll(shiftedKaraokeStyle);
                slideKaraokeColorMap.clear();
                slideKaraokeColorMap.putAll(shiftedKaraokeColor);
                slideKaraokeIntensityMap.clear();
                slideKaraokeIntensityMap.putAll(shiftedKaraokeIntensity);
                slideKaraokeTightMap.clear();
                slideKaraokeTightMap.putAll(shiftedKaraokeTight);
                if (currentSlideTextIndex >= slideTextItems.size()) {
                    currentSlideTextIndex = slideTextItems.size() - 1;
                }
                isLoadingSlideText = true;
                try {
                    rebuildSlideTextSelector();
                    slideTextSelector.setSelectedIndex(currentSlideTextIndex);
                } finally {
                    isLoadingSlideText = false;
                }
                loadSlideTextFromItem(currentSlideTextIndex);
                updateAudioUI();
                loadAudioHlForCurrentText();
                onFormatChanged();
            });

