        // ===== Image FX helpers (toolbar row 4e2) =====

        /** The ticked effects, comma-joined in catalogue order. */
        private String getSlidePicFxString() {
            StringBuilder sb = new StringBuilder();
            for (java.util.Map.Entry<String, JCheckBox> en : slidePicFxChecks.entrySet()) {
                if (en.getValue().isSelected()) {
                    if (sb.length() > 0) sb.append(',');
                    sb.append(en.getKey());
                }
            }
            return sb.toString();
        }

        /** Tick exactly the effects named in a comma-separated list. */
        private void setSlidePicFxChecks(String list) {
            Set<String> want = new HashSet<>();
            if (list != null) {
                for (String tok : list.split(",")) {
                    String t = tok.trim();
                    if (!t.isEmpty()) want.add(t);
                }
            }
            for (java.util.Map.Entry<String, JCheckBox> en : slidePicFxChecks.entrySet()) {
                en.getValue().setSelected(want.contains(en.getKey()));
            }
            updateSlidePicFxButtonText();
        }

        /** Keep the picker button reading like a summary of what is on. */
        private void updateSlidePicFxButtonText() {
            if (slidePicFxButton == null) return;
            List<String> on = new ArrayList<>();
            for (java.util.Map.Entry<String, JCheckBox> en : slidePicFxChecks.entrySet()) {
                if (en.getValue().isSelected()) on.add(en.getKey());
            }
            String label;
            if (on.isEmpty())            label = "FX: None ▾";
            else if (on.size() == 1)     label = "FX: " + on.get(0) + " ▾";
            else                         label = "FX: " + on.get(0) + " +" + (on.size() - 1) + " ▾";
            slidePicFxButton.setText(label);
            slidePicFxButton.setToolTipText(on.isEmpty()
                    ? "Pick any number of effects. They stack."
                    : "<html>" + String.join("<br>", on) + "</html>");
        }

        /** Load a ready-made look into every Image FX control at once. */
        private void applySlidePicFxPreset(PicFxPreset preset) {
            boolean was = isLoadingSlidePicture;
            isLoadingSlidePicture = true;
            try {
                setSlidePicFxChecks(preset.effects);
                slidePicFxPowerSpinner.setValue(clampInt(preset.intensity, 10, 300));
                slidePicFxSpeedSpinner.setValue(clampInt(preset.speed, 10, 400));
                slidePicFxDepthSpinner.setValue(clampInt(preset.shadow, 0, 100));
                slidePicFxEntranceCombo.setSelectedItem(preset.entrance);
                slidePicFxEntranceSecSpinner.setValue(
                        Math.max(0.1, Math.min(8.0, preset.entranceSec)));
                slidePicFxColor = preset.color != null ? preset.color : PIC_FX_DEFAULT_COLOR;
                slidePicFxColorBtn.setBackground(slidePicFxColor);
                slidePicFxColorBtn.repaint();
            } finally {
                isLoadingSlidePicture = was;
            }
        }

        /** Copy this slot's Image FX (nothing else) into the same slot on every
         *  other slide. Locked and title-grid slides are left alone. */
        private void applySlidePictureFxToAllSlides() {
            saveCurrentSlidePictureToItem();
            final int slot = currentSlidePictureIndex;
            if (slot < 0 || slot >= slidePictureItems.size()) return;
            SlidePictureData src = slidePictureItems.get(slot);

            List<SlideRow> targets = new ArrayList<>();
            for (SlideRow row : slideRows) {
                if (row == this || row.isTitleGridSlide || row.isLocked()) continue;
                targets.add(row);
            }
            if (targets.isEmpty()) {
                JOptionPane.showMessageDialog(getPanel(),
                        "No other slides to copy to.\n(Locked and title-grid slides are skipped.)",
                        "Image FX → All Slides", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
            String fxList = src.fxEffects == null || src.fxEffects.isEmpty() ? "(none)" : src.fxEffects;
            int choice = JOptionPane.showConfirmDialog(getPanel(),
                    "Give Pic " + (slot + 1) + " on " + targets.size() + " other slide(s) this FX setup?\n\n"
                            + "Effects: " + fxList + "\n"
                            + "Power " + src.fxIntensity + "%   Speed " + src.fxSpeed + "%   "
                            + "Depth " + src.fxShadow + "\n"
                            + "Entrance: " + src.fxEntrance + " (" + src.fxEntranceSec + "s)\n"
                            + "Layer: " + src.fxLayer + "\n\n"
                            + "Only the FX travel — each slide keeps its own picture and position.",
                    "Image FX → All Slides", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
            if (choice != JOptionPane.OK_OPTION) return;

            isSyncingFormat = true;
            try {
                for (SlideRow row : targets) row.applyImportedSlidePictureFx(slot, src);
            } finally {
                isSyncingFormat = false;
            }
            schedulePreview();
            JOptionPane.showMessageDialog(getPanel(),
                    "Image FX applied to Pic " + (slot + 1) + " on " + targets.size() + " slide(s).",
                    "Image FX → All Slides", JOptionPane.INFORMATION_MESSAGE);
        }

        /** Set one Pic slot's Image FX from another slide's slot, creating the
         *  slot first if this slide does not have that many yet. */
        void applyImportedSlidePictureFx(int index, SlidePictureData src) {
            if (index < 0 || src == null) return;
            saveCurrentSlidePictureToItem();
            while (slidePictureItems.size() <= index) {
                slidePictureItems.add(new SlidePictureData(false, null, null, 50, 50, 20, "Rectangle", 0));
            }
            slidePictureItems.set(index, slidePictureItems.get(index).withFxFrom(src));
            if (currentSlidePictureIndex >= slidePictureItems.size()) currentSlidePictureIndex = 0;
            isLoadingSlidePicture = true;
            try {
                rebuildSlidePicSelector();
                slidePicSelector.setSelectedIndex(currentSlidePictureIndex);
            } finally {
                isLoadingSlidePicture = false;
            }
            loadSlidePictureFromItem(currentSlidePictureIndex);
            schedulePreview();
        }

        // ===== Slide picture dropdown helpers =====

        private void saveCurrentSlidePictureToItem() {
            if (currentSlidePictureIndex < 0 || currentSlidePictureIndex >= slidePictureItems.size()) return;
            slidePictureItems.set(currentSlidePictureIndex, new SlidePictureData(
                    slidePicShowCheck.isSelected(), slidePicLoadedImage, slidePicLoadedFile,
                    (int) slidePicXSpinner.getValue(), (int) slidePicYSpinner.getValue(),
                    (int) slidePicWidthSpinner.getValue(),
                    (String) slidePicShapeCombo.getSelectedItem(),
                    (int) slidePicCornerSpinner.getValue())
                    .withFx(getSlidePicFxString(),
                            (int) slidePicFxPowerSpinner.getValue(),
                            (int) slidePicFxSpeedSpinner.getValue(),
                            slidePicFxColor,
                            (String) slidePicFxEntranceCombo.getSelectedItem(),
                            ((Number) slidePicFxEntranceSecSpinner.getValue()).doubleValue(),
                            (int) slidePicFxDepthSpinner.getValue(),
                            (String) slidePicFxLayerCombo.getSelectedItem()));
        }

        private void loadSlidePictureFromItem(int index) {
            if (index < 0 || index >= slidePictureItems.size()) return;
            isLoadingSlidePicture = true;
            try {
                SlidePictureData item = slidePictureItems.get(index);
                slidePicShowCheck.setSelected(item.show);
                slidePicLoadedImage = item.image;
                slidePicLoadedFile = item.imageFile;
                slidePicXSpinner.setValue(item.x);
                slidePicYSpinner.setValue(item.y);
                slidePicWidthSpinner.setValue(item.widthPct);
                slidePicShapeCombo.setSelectedItem(item.shape);
                slidePicCornerSpinner.setValue(item.cornerRadius);
                setSlidePicFxChecks(item.fxEffects);
                slidePicFxPowerSpinner.setValue(clampInt(item.fxIntensity > 0 ? item.fxIntensity : 100, 10, 300));
                slidePicFxSpeedSpinner.setValue(clampInt(item.fxSpeed > 0 ? item.fxSpeed : 100, 10, 400));
                slidePicFxDepthSpinner.setValue(clampInt(item.fxShadow, 0, 100));
                slidePicFxEntranceCombo.setSelectedItem(
                        item.fxEntrance != null && !item.fxEntrance.isEmpty() ? item.fxEntrance : "None");
                slidePicFxEntranceSecSpinner.setValue(
                        Math.max(0.1, Math.min(8.0, item.fxEntranceSec > 0 ? item.fxEntranceSec : 0.8)));
                slidePicFxLayerCombo.setSelectedItem(
                        item.fxLayer != null && !item.fxLayer.isEmpty() ? item.fxLayer : PIC_LAYER_FRONT);
                slidePicFxColor = item.fxColor != null ? item.fxColor : PIC_FX_DEFAULT_COLOR;
                slidePicFxColorBtn.setBackground(slidePicFxColor);
                slidePicFxColorBtn.repaint();
                slidePicFxPresetCombo.setSelectedIndex(0);
                updateSlidePicPreview();
            } finally {
                isLoadingSlidePicture = false;
            }
        }

        private void rebuildSlidePicSelector() {
            slidePicSelector.removeAllItems();
            for (int i = 0; i < slidePictureItems.size(); i++) {
                slidePicSelector.addItem("Pic " + (i + 1));
            }
        }

        private void updateSlidePicPreview() {
            if (slidePicLoadedImage != null) {
                int pw = slidePicPreviewLabel.getPreferredSize().width;
                int ph = slidePicPreviewLabel.getPreferredSize().height;
                double sc = Math.min((double) pw / slidePicLoadedImage.getWidth(),
                        (double) ph / slidePicLoadedImage.getHeight());
                Image scaled = slidePicLoadedImage.getScaledInstance(
                        Math.max(1, (int) (slidePicLoadedImage.getWidth() * sc)),
                        Math.max(1, (int) (slidePicLoadedImage.getHeight() * sc)),
                        Image.SCALE_SMOOTH);
                slidePicPreviewLabel.setIcon(new ImageIcon(scaled));
                slidePicPreviewLabel.setText(null);
            } else {
                slidePicPreviewLabel.setIcon(null);
                slidePicPreviewLabel.setText("No image");
            }
        }

        private void updateBulkCountLabel() {
            bulkCountLabel.setText(bulkGridItems.size() + (bulkGridItems.size() == 1 ? " image" : " images"));
        }

        private void clearBulkItemUI() {
            isLoadingBulkItem = true;
            try {
                bulkItemLoadedImage = null;
                bulkItemLoadedFile = null;
                bulkItemAudioFile = null;
                bulkItemAudioDurationMs = -1;
                bulkItemPreviewLabel.setIcon(null);
                bulkItemPreviewLabel.setText("No image");
                bulkAudioLabel.setText("No audio");
                setBulkFxToggles("");
                bulkItemSizeSpinner.setValue(100);
                bulkItemXSpinner.setValue(-1);
                bulkItemYSpinner.setValue(-1);
            } finally {
                isLoadingBulkItem = false;
            }
        }

        private void saveBulkItemToList() {
            if (currentBulkIndex < 0 || currentBulkIndex >= bulkGridItems.size()) return;
            SlidePictureData old = bulkGridItems.get(currentBulkIndex);
            int perItemSize = (int) bulkItemSizeSpinner.getValue();
            int manualX = (int) bulkItemXSpinner.getValue(); // -1 = auto
            int manualY = (int) bulkItemYSpinner.getValue(); // -1 = auto
            bulkGridItems.set(currentBulkIndex, new SlidePictureData(
                    true, bulkItemLoadedImage, bulkItemLoadedFile,
                    manualX, manualY, perItemSize, old.shape, old.cornerRadius,
                    bulkItemAudioFile, bulkItemAudioDurationMs,
                    getBulkFxString()));
        }

        private void loadBulkItemFromList(int index) {
            if (index < 0 || index >= bulkGridItems.size()) return;
            isLoadingBulkItem = true;
            try {
                SlidePictureData item = bulkGridItems.get(index);
                bulkItemLoadedImage = item.image;
                bulkItemLoadedFile = item.imageFile;
                bulkItemAudioFile = item.audioFile;
                bulkItemAudioDurationMs = item.audioDurationMs;
                int storedSize = item.widthPct > 0 ? item.widthPct : 100;
                bulkItemSizeSpinner.setValue(Math.min(200, Math.max(10, storedSize)));
                bulkItemXSpinner.setValue(Math.max(-1, Math.min(100, item.x)));
                bulkItemYSpinner.setValue(Math.max(-1, Math.min(100, item.y)));
                updateBulkItemPreview();
                bulkAudioLabel.setText(item.audioFile != null ? item.audioFile.getName() : "No audio");
                setBulkFxToggles(item.audioEffect != null ? item.audioEffect : "");
            } finally {
                isLoadingBulkItem = false;
            }
        }

        private void rebuildBulkItemSelector() {
            bulkItemSelector.removeAllItems();
            if (bulkGridItems.isEmpty()) {
                bulkItemSelector.addItem("(none)");
            } else {
                for (int i = 0; i < bulkGridItems.size(); i++) {
                    bulkItemSelector.addItem("Img " + (i + 1));
                }
            }
        }

        private void updateBulkItemPreview() {
            if (bulkItemLoadedImage != null) {
                int pw = bulkItemPreviewLabel.getPreferredSize().width;
                int ph = bulkItemPreviewLabel.getPreferredSize().height;
                double sc = Math.min((double) pw / bulkItemLoadedImage.getWidth(),
                        (double) ph / bulkItemLoadedImage.getHeight());
                Image scaled = bulkItemLoadedImage.getScaledInstance(
                        Math.max(1, (int) (bulkItemLoadedImage.getWidth() * sc)),
                        Math.max(1, (int) (bulkItemLoadedImage.getHeight() * sc)),
                        Image.SCALE_SMOOTH);
                bulkItemPreviewLabel.setIcon(new ImageIcon(scaled));
                bulkItemPreviewLabel.setText(null);
            } else {
                bulkItemPreviewLabel.setIcon(null);
                bulkItemPreviewLabel.setText("No image");
            }
        }

        private static double[][] getCollageCells(String name) {
            // Each cell: [left%, top%, right%, bottom%] in 0-100 coordinate space
            if (name == null) return null;
            switch (name) {
                // ── 2-image ──────────────────────────────────
                case "Side by Side (2)":
                    return new double[][]{{0,0,50,100},{50,0,100,100}};
                case "Stacked (2)":
                    return new double[][]{{0,0,100,50},{0,50,100,100}};
                case "Feature + Side (2)":
                    return new double[][]{{0,0,65,100},{65,0,100,100}};
                // ── 3-image ──────────────────────────────────
                case "Hero Left (3)":
                    return new double[][]{{0,0,60,100},{60,0,100,50},{60,50,100,100}};
                case "Hero Right (3)":
                    return new double[][]{{0,0,40,50},{0,50,40,100},{40,0,100,100}};
                case "Hero Top (3)":
                    return new double[][]{{0,0,100,60},{0,60,50,100},{50,60,100,100}};
                case "Triptych (3)":
                    return new double[][]{{0,0,33.4,100},{33.3,0,66.7,100},{66.6,0,100,100}};
                // ── 4-image ──────────────────────────────────
                case "Big Left + 3 (4)":
                    return new double[][]{{0,0,60,100},{60,0,100,33.4},{60,33.3,100,66.7},{60,66.6,100,100}};
                case "3 + Big Right (4)":
                    return new double[][]{{0,0,40,33.4},{0,33.3,40,66.7},{0,66.6,40,100},{40,0,100,100}};
                case "Big Top + 3 (4)":
                    return new double[][]{{0,0,100,60},{0,60,33.4,100},{33.3,60,66.7,100},{66.6,60,100,100}};
                case "2×2 Equal (4)":
                    return new double[][]{{0,0,50,50},{50,0,100,50},{0,50,50,100},{50,50,100,100}};
                // ── 5-image ──────────────────────────────────
                case "Magazine (5)":
                    return new double[][]{{0,0,55,65},{55,0,100,33},{55,33,100,65},{0,65,35,100},{35,65,100,100}};
                case "2 + 3 Strips (5)":
                    return new double[][]{{0,0,50,50},{50,0,100,50},{0,50,33.4,100},{33.3,50,66.7,100},{66.6,50,100,100}};
                // ── 6-image ──────────────────────────────────
                case "Feature Mosaic (6)":
                    return new double[][]{{0,0,25,40},{25,0,50,40},{50,0,100,60},{0,40,50,65},{0,65,30,100},{30,65,100,100}};
                default:
                    return null;
            }
        }

        private List<SlidePictureData> computeBulkGridPositions() {
            List<SlidePictureData> out = new ArrayList<>();
            if (bulkGridItems.isEmpty()) return out;

            int slideW = getOutputWidth();
            int slideH = getOutputHeight();
            int shorter = Math.min(slideW, slideH);
            int gapPct    = (int) bulkGapSpinner.getValue();
            int marginPct = (int) bulkMarginSpinner.getValue();
            int sizeScalePct = (int) bulkWidthSpinner.getValue();

            int gapPx    = shorter * gapPct    / 100;  // can be negative (overlap)
            int marginPx = shorter * marginPct / 100;  // always >= 0

            int cornerRadius = (int) bulkCornerSpinner.getValue();
            int borderWidth  = (int) bulkBorderSpinner.getValue();
            Color borderColor = bulkBorderColor;
            int opacity = (int) bulkOpacitySpinner.getValue();
            String fitMode = (String) bulkFitCombo.getSelectedItem();
            if (fitMode == null) fitMode = "Fit";

            // Audio slot base index
            int textAudioCount = 0;
            {
                int maxIdx = -1;
                for (int k : slideAudioFiles.keySet()) if (k > maxIdx) maxIdx = k;
                textAudioCount = maxIdx + 1;
            }
            int bulkAudioSlot = textAudioCount;

            // ── Collage mode ─────────────────────────────────────────────────────────
            String collageName = (String) bulkCollageCombo.getSelectedItem();
            double[][] collageCells = (collageName != null && !collageName.startsWith("—"))
                    ? getCollageCells(collageName) : null;

            if (collageCells != null) {
                int usableW = slideW - 2 * marginPx;
                int usableH = slideH - 2 * marginPx;
                int n = Math.min(bulkGridItems.size(), collageCells.length);
                for (int i = 0; i < n; i++) {
                    SlidePictureData src = bulkGridItems.get(i);
                    double[] cell = collageCells[i];
                    // Map cell [0-100] to pixel rect within the usable (margin-inset) area
                    int leftPx   = marginPx + (int) Math.round(usableW * cell[0] / 100.0);
                    int topPx    = marginPx + (int) Math.round(usableH * cell[1] / 100.0);
                    int rightPx  = marginPx + (int) Math.round(usableW * cell[2] / 100.0);
                    int bottomPx = marginPx + (int) Math.round(usableH * cell[3] / 100.0);
                    // Apply uniform half-gap inset on all 4 sides
                    int halfGap = gapPx / 2;
                    int imgLeft   = leftPx   + halfGap;
                    int imgTop    = topPx    + halfGap;
                    int imgRight  = rightPx  - (gapPx - halfGap);
                    int imgBottom = bottomPx - (gapPx - halfGap);
                    int cellW = Math.max(1, imgRight  - imgLeft);
                    int cellH = Math.max(1, imgBottom - imgTop);
                    int cellCX = imgLeft + cellW / 2;
                    int cellCY = imgTop  + cellH / 2;
                    // Apply global size% and per-item size%
                    int perItemScale = src.widthPct > 0 ? src.widthPct : 100;
                    int finalW = Math.max(1, cellW * sizeScalePct / 100 * perItemScale / 100);
                    int finalH = Math.max(1, cellH * sizeScalePct / 100 * perItemScale / 100);
                    int cx   = src.x >= 0 ? src.x : (int) Math.round(cellCX * 100.0 / slideW);
                    int cy   = src.y >= 0 ? src.y : (int) Math.round(cellCY * 100.0 / slideH);
                    int wPct = (int) Math.round(finalW  * 100.0 / slideW);
                    int hPct = (int) Math.round(finalH  * 100.0 / slideH);
                    int audioActiveIdx = -1;
                    if (src.audioFile != null && src.audioFile.exists() && src.audioDurationMs > 0) {
                        audioActiveIdx = bulkAudioSlot++;
                    }
                    out.add(new SlidePictureData(true, src.image, src.imageFile, cx, cy, Math.max(1, wPct),
                            src.shape, cornerRadius, src.audioFile, src.audioDurationMs,
                            src.audioEffect, Math.max(1, hPct), audioActiveIdx,
                            borderWidth, borderColor, opacity, fitMode));
                }
                return out;
            }

            // ── Grid mode (original logic) ────────────────────────────────────────────
            String layout = (String) bulkLayoutCombo.getSelectedItem();
            int n = bulkGridItems.size();
            int cols, rows;
            if (layout == null || layout.startsWith("1×N")) {
                cols = 1; rows = n;
            } else if (layout.equals("2×1")) { cols = 2; rows = 1;
            } else if (layout.equals("3×1")) { cols = 3; rows = 1;
            } else if (layout.equals("4×1")) { cols = 4; rows = 1;
            } else if (layout.equals("2×2")) { cols = 2; rows = 2;
            } else if (layout.equals("3×2")) { cols = 3; rows = 2;
            } else if (layout.equals("4×2")) { cols = 4; rows = 2;
            } else if (layout.equals("1×2")) { cols = 1; rows = 2;
            } else if (layout.equals("1×3")) { cols = 1; rows = 3;
            } else { cols = (int) Math.ceil(Math.sqrt(n)); rows = (int) Math.ceil((double) n / cols); }

            int usableW = slideW - 2 * marginPx;
            int usableH = slideH - 2 * marginPx;
            int startX  = marginPx;
            int startY  = marginPx;
            int colWidthPx  = Math.max(1, (usableW - (cols - 1) * gapPx) / cols);
            int rowHeightPx = Math.max(1, (usableH - (rows - 1) * gapPx) / rows);
            int imgBoxW = Math.max(1, colWidthPx  * sizeScalePct / 100);
            int imgBoxH = Math.max(1, rowHeightPx * sizeScalePct / 100);

            for (int i = 0; i < n; i++) {
                SlidePictureData src = bulkGridItems.get(i);
                int c = i % cols;
                int r = i / cols;
                if (r >= rows) break;
                int cellCenterX = startX + c * (colWidthPx + gapPx) + colWidthPx / 2;
                int cellCenterY = startY + r * (rowHeightPx + gapPx) + rowHeightPx / 2;
                int perItemScale = src.widthPct > 0 ? src.widthPct : 100;
                int itemBoxW = Math.max(1, imgBoxW * perItemScale / 100);
                int itemBoxH = Math.max(1, imgBoxH * perItemScale / 100);
                int cx   = src.x >= 0 ? src.x : (int) Math.round(cellCenterX * 100.0 / slideW);
                int cy   = src.y >= 0 ? src.y : (int) Math.round(cellCenterY * 100.0 / slideH);
                int wPct = (int) Math.round(itemBoxW * 100.0 / slideW);
                int hPct = (int) Math.round(itemBoxH * 100.0 / slideH);
                int audioActiveIdx = -1;
                if (src.audioFile != null && src.audioFile.exists() && src.audioDurationMs > 0) {
                    audioActiveIdx = bulkAudioSlot++;
                }
                out.add(new SlidePictureData(true, src.image, src.imageFile, cx, cy, Math.max(1, wPct),
                        src.shape, cornerRadius, src.audioFile, src.audioDurationMs,
                        src.audioEffect, Math.max(1, hPct), audioActiveIdx,
                        borderWidth, borderColor, opacity, fitMode));
            }
            return out;
        }

        /** True when this slide carries at least one shape (used by Save Preset). */
        boolean hasSlideAnnotations() { return !slideAnnotationItems.isEmpty(); }

        /** Deep copy of this slide's annotations, for the export pipeline. */
        List<SlideAnnotation> getSlideAnnotationList() {
            List<SlideAnnotation> out = new ArrayList<>(slideAnnotationItems.size());
            for (SlideAnnotation a : slideAnnotationItems) out.add(a.copy());
            return out;
        }

        /** Replace this slide's shapes with copies from {@code src} — used by Load
         *  Preset and by the Shapes box's "Apply to all slides" button. */
        void applySlideAnnotations(List<SlideAnnotation> src) {
            if (src == null) return;
            slideAnnotationItems.clear();
            for (SlideAnnotation a : src) if (a != null) slideAnnotationItems.add(a.copy());
            schedulePreview();
        }

        /** True while the Slide Timer dialog is open — turns on the preview-base cache. */
        private boolean timerDialogOpen = false;
        /** Latest live-preview frame WITHOUT the timer, for the dialog's own canvas. */
        private BufferedImage timerPreviewBase = null;
        /** Scrub position the dialog is showing, ms into the countdown; -1 = auto. */
        private long timerScrubMs = -1;

        /** Countdown instant the editor preview freezes at. */
        private long timerPreviewTimeMs() {
            if (timerScrubMs >= 0) return timerScrubMs;
            return slideTimer == null ? 0 : (long) (slideTimer.totalMs() * 0.35);
        }

        /** This slide's countdown timer (live object — the dialog edits it in place). */
        SlideTimer getSlideTimer() { return slideTimer; }

        /** Replace this slide's timer with a copy of {@code src} (used by Load Preset). */
        void applySlideTimer(SlideTimer src) {
            if (src == null) return;
            slideTimer = src.copy();
            schedulePreview();
        }

        /**
         * Take the master slide's countdown timer, keeping whatever this slide has
         * claimed as its own (CSV-imported target text, badge wording, end sound…).
         * This is how a timer designed once on the first slide reaches the deck.
         */
        void propagateSlideTimerFrom(SlideTimer src) {
            if (src == null) return;
            if (slideTimer == null) slideTimer = new SlideTimer();
            slideTimer.copyPropagatedFrom(src);
            schedulePreview();
        }

        /** Point this slide's countdown at one of its texts (0 = no target text).
         *  Set by Dict Import's TIMER_TARGET column and by the Slide Timer box. */
        void setSlideTimerTarget(int textNumber) {
            if (slideTimer == null) slideTimer = new SlideTimer();
            slideTimer.endTextIndex = Math.max(0, textNumber);
            schedulePreview();
        }

        /** Give this slide its own "play when it ends" sound. An empty path with
         *  {@code silent} false falls back to the first slide's sound; {@code silent}
         *  keeps the slide quiet instead. Set by Dict Import's TIMER_END_AUDIO. */
        void setSlideTimerEndAudio(String path, boolean silent) {
            if (slideTimer == null) slideTimer = new SlideTimer();
            slideTimer.endAudioPath = path == null ? "" : path;
            slideTimer.endAudioSilent = silent;
            schedulePreview();
        }

        /**
         * Where the timer starts on THIS slide's timeline, in ms — the same
         * resolution the exporter does in collectSlides, so the editor preview and
         * the exported video agree on "after all audio + 1 s".
         */
        int resolvedTimerStartMs() {
            if (slideTimer == null) return 0;
            int[][] tl = audioTimeline(getSlideAudioDurationsMsList(),
                    getSlideAudioFilesList(), getAudioGapMs());
            return slideTimer.resolveStartMs(tl[0], tl[1], totalAudioMs(tl[1]));
        }

        List<SlidePictureData> getSlidePictureDataList() {
            saveCurrentSlidePictureToItem();
            List<SlidePictureData> result = new ArrayList<>(slidePictureItems);
            if (bulkGridShowCheck != null && bulkGridShowCheck.isSelected() && !bulkGridItems.isEmpty()) {
                result.addAll(computeBulkGridPositions());
            }
            return result;
        }

        /** The Pic slots the toolbar edits, WITHOUT the computed bulk-grid cells.
         *  This is what propagate and presets carry: bulk-grid entries are derived
         *  from that slide's own uploaded images, so broadcasting them would grow
         *  phantom Pic slots on every other slide. */
        List<SlidePictureData> getSlidePictureFormats() {
            saveCurrentSlidePictureToItem();
            return new ArrayList<>(slidePictureItems);
        }

        /** Propagate default: geometry only, each slide keeps its own picture. */
        void applySlidePictureFormats(List<SlidePictureData> formats) {
            applySlidePictureFormats(formats, false, false);
        }

        /**
         * Copy Pic slots from a master slide, a preset, or the "⇊ All" button.
         *
         * @param withImages       when true the picture itself travels too, not just
         *                         its position/size/shape. Ordinary propagate passes
         *                         false so a per-slide photo is never clobbered.
         * @param clearMissingImages when true a source slot with no picture empties
         *                         the target slot as well (an exact copy). Preset load
         *                         passes false so a preset that never had a picture
         *                         leaves each slide's own image alone.
         */
        void applySlidePictureFormats(List<SlidePictureData> formats,
                                      boolean withImages, boolean clearMissingImages) {
            if (formats == null || formats.isEmpty()) return;
            // Ensure we have at least as many items as the source.
            while (slidePictureItems.size() < formats.size()) {
                slidePictureItems.add(new SlidePictureData(false, null, null, 50, 50, 20, "Rectangle", 0));
            }
            for (int i = 0; i < formats.size(); i++) {
                SlidePictureData fmt = formats.get(i);
                SlidePictureData existing = slidePictureItems.get(i);
                boolean takeImage = withImages && (fmt.image != null || clearMissingImages);
                BufferedImage img  = takeImage ? fmt.image     : existing.image;
                File          file = takeImage ? fmt.imageFile : existing.imageFile;
                boolean show = takeImage ? fmt.show
                        : (existing.image != null ? existing.show : fmt.show);
                slidePictureItems.set(i, new SlidePictureData(show, img, file,
                        clampInt(fmt.x, 0, 100), clampInt(fmt.y, 0, 100),
                        clampInt(fmt.widthPct, 1, 100), fmt.shape,
                        clampInt(fmt.cornerRadius, 0, 200)).withFxFrom(fmt));
            }
            if (currentSlidePictureIndex >= slidePictureItems.size()) {
                currentSlidePictureIndex = 0;
            }
            isLoadingSlidePicture = true;
            try {
                rebuildSlidePicSelector();
                slidePicSelector.setSelectedIndex(currentSlidePictureIndex);
            } finally {
                isLoadingSlidePicture = false;
            }
            loadSlidePictureFromItem(currentSlidePictureIndex);
            schedulePreview();
        }

        /**
         * Set one Pic slot from an import or a bulk apply. A null argument leaves
         * that field as it was, so a sheet can carry only geometry (or only the
         * image). Slots beyond what this slide has are created on the way.
         */
        void applyImportedSlidePicture(int index, BufferedImage img, File imgFile,
                                       Integer x, Integer y, Integer widthPct,
                                       String shape, Integer cornerRadius, Boolean show) {
            if (index < 0) return;
            saveCurrentSlidePictureToItem();
            while (slidePictureItems.size() <= index) {
                slidePictureItems.add(new SlidePictureData(false, null, null, 50, 50, 20, "Rectangle", 0));
            }
            SlidePictureData cur = slidePictureItems.get(index);
            BufferedImage newImg = (img != null) ? img : cur.image;
            File newFile = (img != null) ? imgFile : cur.imageFile;
            // A freshly supplied picture switches its slot on; otherwise the slot
            // keeps whatever the slide already decided.
            boolean newShow = (show != null) ? show : (img != null || cur.show);
            slidePictureItems.set(index, new SlidePictureData(newShow, newImg, newFile,
                    clampInt(x != null ? x : cur.x, 0, 100),
                    clampInt(y != null ? y : cur.y, 0, 100),
                    clampInt(widthPct != null ? widthPct : cur.widthPct, 1, 100),
                    shape != null ? shape : cur.shape,
                    clampInt(cornerRadius != null ? cornerRadius : cur.cornerRadius, 0, 200))
                    .withFxFrom(cur));
            if (currentSlidePictureIndex >= slidePictureItems.size()) {
                currentSlidePictureIndex = 0;
            }
            isLoadingSlidePicture = true;
            try {
                rebuildSlidePicSelector();
                slidePicSelector.setSelectedIndex(currentSlidePictureIndex);
            } finally {
                isLoadingSlidePicture = false;
            }
            loadSlidePictureFromItem(currentSlidePictureIndex);
            schedulePreview();
        }

        /**
         * Push this slide's current Pic slot onto every other slide — the one-upload
         * path for a logo or watermark that belongs on the whole deck. Ordinary
         * propagate carries only the geometry, so without this each slide would need
         * its own Browse. Locked and title-grid slides are left alone.
         */
        private void applyThisSlidePictureToAllSlides() {
            if (slidePicLoadedImage == null) {
                // Empty slot: ask for the picture first, so a single upload can land
                // on the whole deck in one go.
                JFileChooser fc = new JFileChooser();
                fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter(
                        "Images", "jpg", "jpeg", "png", "gif", "bmp", "webp", "avif", "heif", "heic"));
                if (fc.showOpenDialog(getPanel()) != JFileChooser.APPROVE_OPTION) return;
                try {
                    File f = fc.getSelectedFile();
                    BufferedImage img = loadImageFile(f);
                    if (img == null) throw new IOException("Unsupported image format.");
                    slidePicLoadedImage = img;
                    slidePicLoadedFile = f;
                    updateSlidePicPreview();
                    slidePicShowCheck.setSelected(true);
                } catch (Exception ex) {
                    JOptionPane.showMessageDialog(getPanel(),
                            "Failed to load image: " + ex.getMessage(),
                            "Picture → All Slides", JOptionPane.ERROR_MESSAGE);
                    return;
                }
            }
            saveCurrentSlidePictureToItem();
            final int slot = currentSlidePictureIndex;
            SlidePictureData src = slidePictureItems.get(slot);

            List<SlideRow> targets = new ArrayList<>();
            for (SlideRow row : slideRows) {
                if (row == this || row.isTitleGridSlide || row.isLocked()) continue;
                targets.add(row);
            }
            if (targets.isEmpty()) {
                JOptionPane.showMessageDialog(getPanel(),
                        "No other slides to copy to.\n(Locked and title-grid slides are skipped.)",
                        "Picture → All Slides", JOptionPane.INFORMATION_MESSAGE);
                return;
            }

            String[] opts = {"Picture + position", "Position only", "Cancel"};
            int choice = JOptionPane.showOptionDialog(getPanel(),
                    "Put Pic " + (slot + 1) + " on " + targets.size() + " other slide(s)?\n\n"
                            + (src.imageFile != null ? "Image: " + src.imageFile.getName() + "\n" : "")
                            + "Position " + src.x + "%, " + src.y + "%    Width " + src.widthPct + "%    "
                            + src.shape + (src.cornerRadius > 0 ? " (radius " + src.cornerRadius + ")" : "")
                            + "\n\nLocked and title-grid slides are skipped.",
                    "Picture → All Slides", JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE,
                    null, opts, opts[0]);
            if (choice != 0 && choice != 1) return;
            boolean withImage = (choice == 0);

            isSyncingFormat = true;
            try {
                for (SlideRow row : targets) {
                    row.applyImportedSlidePicture(slot,
                            withImage ? src.image : null,
                            withImage ? src.imageFile : null,
                            src.x, src.y, src.widthPct, src.shape, src.cornerRadius,
                            withImage ? src.show : null);
                    // The look travels with the placement, so a deck-wide logo
                    // does not glow on one slide and sit flat on the next.
                    row.applyImportedSlidePictureFx(slot, src);
                }
            } finally {
                isSyncingFormat = false;
            }
            schedulePreview();
            JOptionPane.showMessageDialog(getPanel(),
                    "Pic " + (slot + 1) + (withImage ? " and its picture" : " position")
                            + " applied to " + targets.size() + " slide(s).",
                    "Picture → All Slides", JOptionPane.INFORMATION_MESSAGE);
        }

        private void onFormatChanged() {
            schedulePreview();
            updateTextAreaStyle();
            if (!isSyncingFormat && !isLivePreviewActive && !isTitleGridSlide && !slideRows.isEmpty()) {
                for (SlideRow row : slideRows) {
                    if (!row.isTitleGridSlide) {
                        if (row == this) {
                            syncFormattingFromFirstSlide();
                        }
                        break;
                    }
                }
            }
        }

        private static JPanel createToolbarSeparator() {
            JPanel sep = new JPanel();
            sep.setBackground(new Color(70, 73, 78));
            sep.setPreferredSize(new Dimension(Integer.MAX_VALUE, 1));
            sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
            sep.setMinimumSize(new Dimension(0, 1));
            return sep;
        }

        private JLabel styledLabel(String text) {
            JLabel l = new JLabel(text);
            l.setForeground(Color.LIGHT_GRAY);
            l.setFont(new Font("Segoe UI", Font.PLAIN, 11));
            return l;
        }

        private String getBulkFxString() {
            StringBuilder sb = new StringBuilder();
            if (bulkFxGlow.isSelected())      { if (sb.length()>0) sb.append(','); sb.append("Glow"); }
            if (bulkFxPulse.isSelected())     { if (sb.length()>0) sb.append(','); sb.append("Scale Pulse"); }
            if (bulkFxPop.isSelected())       { if (sb.length()>0) sb.append(','); sb.append("Pop"); }
            if (bulkFxHeartbeat.isSelected()) { if (sb.length()>0) sb.append(','); sb.append("Heartbeat"); }
            if (bulkFxColorScan.isSelected()) { if (sb.length()>0) sb.append(','); sb.append("Color Scan"); }
            if (bulkFxShine.isSelected())     { if (sb.length()>0) sb.append(','); sb.append("Shine"); }
            if (bulkFxBounce.isSelected())    { if (sb.length()>0) sb.append(','); sb.append("Bounce"); }
            return sb.toString();
        }

        private void setBulkFxToggles(String fxStr) {
            String s = fxStr != null ? fxStr : "";
            // "Scale Pulse" contains "Pulse"; check the full token to avoid Pop/Pulse clashes
            bulkFxGlow.setSelected(s.contains("Glow"));
            bulkFxPulse.setSelected(s.contains("Scale Pulse"));
            bulkFxPop.setSelected(s.contains("Pop"));
            bulkFxHeartbeat.setSelected(s.contains("Heartbeat"));
            bulkFxColorScan.setSelected(s.contains("Color Scan"));
            bulkFxShine.setSelected(s.contains("Shine"));
            bulkFxBounce.setSelected(s.contains("Bounce"));
            updateBulkFxButtonText();
        }

        private void updateBulkFxButtonText() {
            int count = 0;
            String single = null;
            for (Object[] o : new Object[][]{
                    {bulkFxGlow, "Glow"}, {bulkFxPulse, "Pulse"}, {bulkFxPop, "Pop"},
                    {bulkFxHeartbeat, "Heartbeat"}, {bulkFxColorScan, "Scan"},
                    {bulkFxShine, "Shine"}, {bulkFxBounce, "Bounce"}}) {
                if (((JCheckBoxMenuItem) o[0]).isSelected()) { count++; single = (String) o[1]; }
            }
            String label;
            if (count == 0) label = "FX: None ▾";
            else if (count == 1) label = "FX: " + single + " ▾";
            else label = "FX: " + count + " effects ▾";
            bulkFxButton.setText(label);
        }

        void schedulePreview() {
            previewTimer.restart();
        }

        private void updateTextAreaStyle() {
            String fontName = (String) fontCombo.getSelectedItem();
            int size = Math.min((int) sizeSpinner.getValue(), 40);
            int style = Font.PLAIN;
            if (boldBtn.isSelected()) style |= Font.BOLD;
            if (italicBtn.isSelected()) style |= Font.ITALIC;
            textArea.setFont(new Font(fontName, style, Math.max(size, 12)));
            textArea.setForeground(selectedColor);
        }

