        int getTextShiftX() { return (int) textShiftXSpinner.getValue(); }

        File getSlideAudioFile() { return slideAudioFiles.get(0); }
        int getSlideAudioDurationMs() {
            int total = 0;
            for (int d : slideAudioDurationsMs.values()) {
                if (d > 0) total += d;
            }
            return total > 0 ? total : -1;
        }

        java.util.List<File> getSlideAudioFilesList() {
            int maxIdx = -1;
            for (int k : slideAudioFiles.keySet()) if (k > maxIdx) maxIdx = k;
            int gapMs = getAudioGapMs();
            java.util.List<File> result = new java.util.ArrayList<>();
            for (int i = 0; i <= maxIdx; i++) {
                File primary = slideAudioFiles.get(i);
                File second  = slideAudioFiles2.get(i);
                Integer d1 = slideAudioDurationsMs.get(i);
                Integer d2 = slideAudioDurationsMs2.get(i);
                // When a text has a second audio, merge (primary + gap + second)
                // into a single clip so the text keeps ONE audio slot — the
                // highlight/karaoke/quiz code all key visuals off index==textIndex.
                // Predicate must match getSlideAudioDurationsMsList() exactly so the
                // parallel files/durations lists never diverge.
                if (primary != null && primary.exists() && d1 != null && d1 > 0
                        && second != null && second.exists() && d2 != null && d2 > 0) {
                    result.add(buildCombinedAudioFile(primary, second, gapMs));
                } else {
                    result.add(primary);
                }
            }
            // Append audio files from bulk-grid images (each plays in sequence).
            if (bulkGridShowCheck != null && bulkGridShowCheck.isSelected()) {
                saveBulkItemToList();
                for (SlidePictureData pic : bulkGridItems) {
                    if (pic.audioFile != null && pic.audioFile.exists()
                            && pic.audioDurationMs > 0) {
                        result.add(pic.audioFile);
                    }
                }
            }
            return result;
        }

        java.util.List<Integer> getSlideAudioDurationsMsList() {
            int maxIdx = -1;
            for (int k : slideAudioDurationsMs.keySet()) if (k > maxIdx) maxIdx = k;
            int gapMs = getAudioGapMs();
            java.util.List<Integer> result = new java.util.ArrayList<>();
            for (int i = 0; i <= maxIdx; i++) {
                Integer d = slideAudioDurationsMs.get(i);
                int dur = d != null ? d : 0;
                // Parallel to getSlideAudioFilesList(): if this text carries a
                // merged (primary + gap + second) clip, report the combined length.
                File primary = slideAudioFiles.get(i);
                File second  = slideAudioFiles2.get(i);
                Integer d2 = slideAudioDurationsMs2.get(i);
                if (dur > 0 && primary != null && primary.exists()
                        && second != null && second.exists() && d2 != null && d2 > 0) {
                    dur += gapMs + d2;
                }
                result.add(dur);
            }
            // Append durations from bulk-grid images, parallel to audio files.
            if (bulkGridShowCheck != null && bulkGridShowCheck.isSelected()) {
                for (SlidePictureData pic : bulkGridItems) {
                    if (pic.audioFile != null && pic.audioFile.exists()
                            && pic.audioDurationMs > 0) {
                        result.add(pic.audioDurationMs);
                    }
                }
            }
            return result;
        }

        int getAudioGapMs() { return (int)(((Number) audioGapSpinner.getValue()).doubleValue() * 1000); }

        /** Parallel to getSlideAudioFilesList() — element N is the word-timing
         *  list for audioFiles[N], or null when that audio hasn't been synced. */
        java.util.List<java.util.List<WordTiming>> getSlideAudioWordTimingsList() {
            int maxIdx = -1;
            for (int k : slideAudioFiles.keySet()) if (k > maxIdx) maxIdx = k;
            if (maxIdx < 0) return new java.util.ArrayList<>();
            java.util.List<java.util.List<WordTiming>> result = new java.util.ArrayList<>();
            for (int i = 0; i <= maxIdx; i++) result.add(slideAudioWordTimingsMap.get(i));
            return result;
        }

        /** Update the toolbar7d "(N words)" / "(no audio)" / "(not synced)" label
         *  for the currently-selected text row. Also enables/disables the buttons
         *  and re-binds the Word FX combo / color button to whatever was stored
         *  for the now-active text row. */
        private void refreshKaraokeStatus() {
            if (karaokeStatusLabel == null) return;
            File audio = slideAudioFiles.get(currentSlideTextIndex);
            List<WordTiming> t = slideAudioWordTimingsMap.get(currentSlideTextIndex);
            if (audio == null) {
                karaokeStatusLabel.setText("(no audio)");
                karaokeStatusLabel.setForeground(new Color(140, 140, 140));
                karaokeSyncBtn.setEnabled(false);
                karaokeClearBtn.setEnabled(false);
            } else if (t == null || t.isEmpty()) {
                karaokeStatusLabel.setText("(not synced)");
                karaokeStatusLabel.setForeground(new Color(210, 180, 120));
                karaokeSyncBtn.setEnabled(true);
                karaokeClearBtn.setEnabled(false);
            } else {
                karaokeStatusLabel.setText("✓ " + t.size() + " words");
                karaokeStatusLabel.setForeground(new Color(140, 230, 170));
                karaokeSyncBtn.setEnabled(true);
                karaokeClearBtn.setEnabled(true);
            }
            // Rebind Word FX combo + color button to the per-text-row stored values.
            isLoadingKaraoke = true;
            try {
                String style = slideKaraokeStyleMap.getOrDefault(currentSlideTextIndex, DEFAULT_KARAOKE_STYLE);
                if (karaokeStyleCombo != null) karaokeStyleCombo.setSelectedItem(style);
                Color c = slideKaraokeColorMap.getOrDefault(currentSlideTextIndex, DEFAULT_KARAOKE_COLOR);
                karaokeColor = c;
                if (karaokeColorBtn != null) karaokeColorBtn.setBackground(c);
                if (karaokeIntensitySp != null) karaokeIntensitySp.setValue(
                        slideKaraokeIntensityMap.getOrDefault(currentSlideTextIndex, DEFAULT_KARAOKE_INTENSITY));
                if (karaokeTightSp != null) karaokeTightSp.setValue(
                        slideKaraokeTightMap.getOrDefault(currentSlideTextIndex, DEFAULT_KARAOKE_TIGHT));
            } finally {
                isLoadingKaraoke = false;
            }
        }

        /** Listener for both the Word FX combo and the karaoke color picker —
         *  writes back to the per-text-row map and re-renders the preview. */
        private void onKaraokeUiChanged() {
            if (isLoadingKaraoke) return;
            String style = (String) karaokeStyleCombo.getSelectedItem();
            slideKaraokeStyleMap.put(currentSlideTextIndex, style != null ? style : DEFAULT_KARAOKE_STYLE);
            slideKaraokeColorMap.put(currentSlideTextIndex, karaokeColor);
            if (karaokeIntensitySp != null)
                slideKaraokeIntensityMap.put(currentSlideTextIndex, (Integer) karaokeIntensitySp.getValue());
            if (karaokeTightSp != null)
                slideKaraokeTightMap.put(currentSlideTextIndex, (Integer) karaokeTightSp.getValue());
            schedulePreview();
            // If this is the master slide, broadcast Word FX style/color to the rest
            // — same trigger pattern as onFormatChanged().
            if (!isSyncingFormat && !isLivePreviewActive && !isTitleGridSlide && !slideRows.isEmpty()) {
                for (SlideRow row : slideRows) {
                    if (!row.isTitleGridSlide) {
                        if (row == this) syncFormattingFromFirstSlide();
                        break;
                    }
                }
            }
        }

